    #[test]
    fn permission_queue_withdrawing_the_visible_card_promotes_the_next() {
        // The agent took back the approval on screen (claude aborts a tool
        // call's permission when the call is stopped) while another waits: the
        // dead card must give way now, not hold the screen until the turn ends.
        let (mut queue, log) = stub_permission_queue();
        admit_stub_permission(&mut queue, &log, "a");
        admit_stub_permission(&mut queue, &log, "b");

        let Some(Departure::Shown { next }) = queue.withdraw("a") else {
            panic!("`a` was the card on screen");
        };
        assert_eq!(next.map(|c| c.request_id).as_deref(), Some("b"));
        assert_eq!(queue.showing.as_deref(), Some("b"));
        assert_eq!(
            log.lock().unwrap().clone(),
            vec![("a".to_string(), StubPermissionOutcome::Cancelled)],
            "only the withdrawn request is answered, and as cancelled"
        );
    }

    #[test]
    fn permission_queue_never_shows_a_card_withdrawn_while_queued() {
        let (mut queue, log) = stub_permission_queue();
        admit_stub_permission(&mut queue, &log, "a");
        admit_stub_permission(&mut queue, &log, "b");
        admit_stub_permission(&mut queue, &log, "c");

        assert!(matches!(queue.withdraw("b"), Some(Departure::Queued)));
        assert_eq!(
            queue.showing.as_deref(),
            Some("a"),
            "the screen is untouched"
        );
        assert_eq!(queue.waiting_len(), 1);
        assert_eq!(
            queue
                .resolve("a", "allow".into())
                .next
                .map(|c| c.request_id)
                .as_deref(),
            Some("c"),
            "answering the visible card skips straight past the withdrawn one"
        );
        assert_eq!(
            log.lock().unwrap().clone(),
            vec![
                ("b".to_string(), StubPermissionOutcome::Cancelled),
                ("a".to_string(), StubPermissionOutcome::Selected),
            ]
        );
    }

    /// A burst of withdrawals: `b` is already taken back when `a` leaves the
    /// screen, but its own watcher has not run yet. Promoting it would flash a
    /// dead card on every client and push it to chat channels, so the queue
    /// answers it `Cancelled` on the spot and shows `c` — whichever way `a`
    /// left.
    #[test]
    fn permission_queue_never_promotes_a_card_already_withdrawn() {
        for withdraw_a in [false, true] {
            let (mut queue, log) = stub_permission_queue();
            admit_stub_permission(&mut queue, &log, "a");
            let b_withdrawn = Arc::new(std::sync::atomic::AtomicBool::new(false));
            admit_stub_permission_with_marker(&mut queue, &log, "b", Arc::clone(&b_withdrawn));
            admit_stub_permission(&mut queue, &log, "c");
            b_withdrawn.store(true, std::sync::atomic::Ordering::SeqCst);

            let next = if withdraw_a {
                let Some(Departure::Shown { next }) = queue.withdraw("a") else {
                    panic!("`a` was the card on screen");
                };
                next
            } else {
                queue.resolve("a", "allow".into()).next
            };
            assert_eq!(next.map(|c| c.request_id).as_deref(), Some("c"));
            assert_eq!(queue.showing.as_deref(), Some("c"));
            assert_eq!(queue.waiting_len(), 0);
            let a_answer = if withdraw_a {
                StubPermissionOutcome::Cancelled
            } else {
                StubPermissionOutcome::Selected
            };
            assert_eq!(
                log.lock().unwrap().clone(),
                vec![
                    ("b".to_string(), StubPermissionOutcome::Cancelled),
                    ("a".to_string(), a_answer),
                ]
            );
            // `b`'s watcher arriving afterwards finds nothing left to do.
            assert!(queue.withdraw("b").is_none());
        }

        // When every card behind the departing one is withdrawn, nothing is
        // promoted and the screen clears.
        let (mut queue, log) = stub_permission_queue();
        admit_stub_permission(&mut queue, &log, "a");
        let b_withdrawn = Arc::new(std::sync::atomic::AtomicBool::new(true));
        admit_stub_permission_with_marker(&mut queue, &log, "b", b_withdrawn);
        assert!(queue.resolve("a", "allow".into()).next.is_none());
        assert_eq!(queue.showing, None);
        assert_eq!(queue.waiting_len(), 0);
        assert_eq!(
            log.lock().unwrap().clone(),
            vec![
                ("b".to_string(), StubPermissionOutcome::Cancelled),
                ("a".to_string(), StubPermissionOutcome::Selected),
            ]
        );
    }

    #[test]
    fn permission_queue_withdrawal_after_an_answer_is_a_no_op() {
        // The race a withdrawal loses whenever the user clicked first.
        let (mut queue, log) = stub_permission_queue();
        admit_stub_permission(&mut queue, &log, "a");
        assert!(queue.resolve("a", "allow".into()).answered);
        assert!(queue.withdraw("a").is_none());
        assert!(queue.withdraw("never-admitted").is_none());
        assert_eq!(
            log.lock().unwrap().clone(),
            vec![("a".to_string(), StubPermissionOutcome::Selected)]
        );
    }

    /// A card's watcher never retires anything once the card has left the
    /// queue, even when the withdrawal is ready at the same moment — a plain
    /// `tokio::select!` would pick either arm at random, hence the repeats.
    #[tokio::test]
    async fn a_settled_permission_is_never_treated_as_withdrawn() {
        for _ in 0..64 {
            let (settled_tx, settled_rx) = oneshot::channel::<()>();
            drop(settled_tx);
            assert!(!withdrawn_while_parked(settled_rx, std::future::ready(())).await);
        }
        let (_parked, settled_rx) = oneshot::channel::<()>();
        assert!(withdrawn_while_parked(settled_rx, std::future::ready(())).await);
    }

    /// The withdrawal path end to end, over the real runtime: the agent raises
    /// `session/request_permission` and takes it back with `$/cancel_request`,
    /// exactly as claude-agent-acp does when the tool call's signal aborts. It
    /// must get its answer (`Cancelled`) without anyone touching the card, and
    /// the card the client showed must be retracted.
    #[tokio::test]
    async fn an_agent_withdrawing_a_permission_request_retires_its_card() {
        use agent_client_protocol::schema::v1::{
            PermissionOption, ToolCallUpdate, ToolCallUpdateFields,
        };
        use agent_client_protocol::Channel;

        let (client_end, agent_end) = Channel::duplex();
        let state = Arc::new(RwLock::new(SessionState::new(
            "conn-test".to_string(),
            AgentType::ClaudeCode,
            None,
            "win".to_string(),
            None,
        )));
        let perms = PendingPermissions::default();

        let agent = tokio::spawn(Agent.builder().connect_with(
            agent_end,
            async |cx: ConnectionTo<Client>| {
                let request = cx.send_request_to(
                    Client,
                    RequestPermissionRequest::new(
                        SessionId::new("s1"),
                        ToolCallUpdate::new("call-1", ToolCallUpdateFields::new().title("Bash")),
                        vec![PermissionOption::new(
                            "allow",
                            "Allow",
                            PermissionOptionKind::AllowOnce,
                        )],
                    ),
                );
                request.cancel()?;
                request.block_task().await
            },
        ));

        let client = tokio::spawn({
            let state = Arc::clone(&state);
            let perms = perms.clone();
            Client
                .builder()
                .on_receive_request(
                    async move |req: RequestPermissionRequest,
                                responder: Responder<RequestPermissionResponse>,
                                cx: ConnectionTo<Agent>| {
                        handle_permission_request(
                            &cx,
                            &state,
                            &EventEmitter::Noop,
                            &perms,
                            "/tmp",
                            AgentType::ClaudeCode,
                            req,
                            responder,
                        )
                        .await;
                        Ok(())
                    },
                    on_receive_request!(),
                )
                .connect_with(client_end, async |_cx: ConnectionTo<Agent>| {
                    std::future::pending::<Result<(), agent_client_protocol::Error>>().await
                })
        });

        let response = tokio::time::timeout(std::time::Duration::from_secs(5), agent)
            .await
            .expect("a withdrawn request is answered without the user")
            .expect("agent task")
            .expect("a response, not an error");
        client.abort();
        assert!(
            matches!(response.outcome, RequestPermissionOutcome::Cancelled),
            "{:?}",
            response.outcome
        );

        let guard = state.read().await;
        let events = guard.recent_events_after(0).expect("events recorded");
        let shown = events
            .iter()
            .find_map(|e| match &e.payload {
                AcpEvent::PermissionRequest { request_id, .. } => Some(request_id.clone()),
                _ => None,
            })
            .expect("the card was shown");
        assert!(
            events.iter().any(|e| matches!(
                &e.payload,
                AcpEvent::PermissionResolved {
                    request_id,
                    option_id: None,
                    origin: None,
                } if *request_id == shown
            )),
            "the card must be retracted, not left up with no one behind it, and \
             a withdrawal names no option and no answerer"
        );
        assert!(
            !events
                .iter()
                .any(|e| matches!(e.payload, AcpEvent::ToolApproval { .. })),
            "a withdrawal decided nothing about the call"
        );
        assert!(perms.lock().await.showing.is_none());
    }

    /// The answer that takes effect is reported with its option and who gave
    /// it; a second answer to the same card changes nothing and reports
    /// nothing — even when it picks the very same option, which is why the
    /// author cannot be inferred by comparing options.
    #[tokio::test]
    async fn the_effective_permission_answer_is_reported_with_its_origin() {
        use agent_client_protocol::schema::v1::{
            PermissionOption, ToolCallUpdate, ToolCallUpdateFields,
        };
        use agent_client_protocol::Channel;

        let (client_end, agent_end) = Channel::duplex();
        let state = Arc::new(RwLock::new(SessionState::new(
            "conn-test".to_string(),
            AgentType::ClaudeCode,
            None,
            "win".to_string(),
            None,
        )));
        let perms = PendingPermissions::default();

        let agent = tokio::spawn(Agent.builder().connect_with(
            agent_end,
            async |cx: ConnectionTo<Client>| {
                cx.send_request_to(
                    Client,
                    RequestPermissionRequest::new(
                        SessionId::new("s1"),
                        ToolCallUpdate::new("call-1", ToolCallUpdateFields::new().title("Bash")),
                        vec![
                            PermissionOption::new("deny", "Deny", PermissionOptionKind::RejectOnce),
                            PermissionOption::new(
                                "allow",
                                "Allow",
                                PermissionOptionKind::AllowOnce,
                            ),
                        ],
                    ),
                )
                .block_task()
                .await
            },
        ));

        let client = tokio::spawn({
            let state = Arc::clone(&state);
            let perms = perms.clone();
            Client
                .builder()
                .on_receive_request(
                    async move |req: RequestPermissionRequest,
                                responder: Responder<RequestPermissionResponse>,
                                cx: ConnectionTo<Agent>| {
                        handle_permission_request(
                            &cx,
                            &state,
                            &EventEmitter::Noop,
                            &perms,
                            "/tmp",
                            AgentType::ClaudeCode,
                            req,
                            responder,
                        )
                        .await;
                        Ok(())
                    },
                    on_receive_request!(),
                )
                .connect_with(client_end, async |_cx: ConnectionTo<Agent>| {
                    std::future::pending::<Result<(), agent_client_protocol::Error>>().await
                })
        });

        let shown = tokio::time::timeout(std::time::Duration::from_secs(5), async {
            loop {
                if let Some(id) = perms.lock().await.showing.clone() {
                    break id;
                }
                tokio::time::sleep(std::time::Duration::from_millis(5)).await;
            }
        })
        .await
        .expect("the card is shown");

        let policy = PermissionAnswerOrigin::CliPolicy {
            run_id: "run-1".to_string(),
        };
        resolve_permission(
            &perms,
            &state,
            &EventEmitter::Noop,
            shown.clone(),
            "deny".to_string(),
            policy.clone(),
        )
        .await;
        // The same option again, from a person: a no-op.
        resolve_permission(
            &perms,
            &state,
            &EventEmitter::Noop,
            shown.clone(),
            "deny".to_string(),
            PermissionAnswerOrigin::User,
        )
        .await;

        let response = tokio::time::timeout(std::time::Duration::from_secs(5), agent)
            .await
            .expect("the agent gets its answer")
            .expect("agent task")
            .expect("a response, not an error");
        client.abort();
        match response.outcome {
            RequestPermissionOutcome::Selected(selected) => {
                assert_eq!(selected.option_id.to_string(), "deny");
            }
            other => panic!("expected the selected option, got {other:?}"),
        }

        let guard = state.read().await;
        let events = guard.recent_events_after(0).expect("events recorded");
        let resolved: Vec<_> = events
            .iter()
            .filter_map(|e| match &e.payload {
                AcpEvent::PermissionResolved {
                    request_id,
                    option_id,
                    origin,
                } => Some((request_id.clone(), option_id.clone(), origin.clone())),
                _ => None,
            })
            .collect();
        assert_eq!(
            resolved,
            vec![(shown, Some("deny".to_string()), Some(policy))],
            "exactly one report, naming the effective option and its answerer"
        );

        // …followed by exactly one record of what it decided about the call.
        let resolved_at = events
            .iter()
            .position(|e| matches!(e.payload, AcpEvent::PermissionResolved { .. }))
            .expect("resolved");
        let approvals: Vec<_> = events
            .iter()
            .enumerate()
            .filter_map(|(i, e)| match &e.payload {
                AcpEvent::ToolApproval { approval } => Some((i, approval.clone())),
                _ => None,
            })
            .collect();
        assert_eq!(approvals.len(), 1, "one record per effective answer");
        let (approval_at, approval) = &approvals[0];
        assert!(*approval_at > resolved_at, "after the card is retired");
        assert_eq!(approval.tool_call_id, "call-1");
        assert_eq!(approval.option_kind, "reject_once");
        assert_eq!(approval.option_name, "Deny");
        assert_eq!(approval.origin, "cli_policy");
        assert_eq!(guard.tool_approvals, vec![approval.clone()]);
    }

    fn minimax_tool_call(id: &str, status: &str, raw_input: &str) -> AcpEvent {
        AcpEvent::ToolCall {
            tool_call_id: id.to_string(),
            title: "write".to_string(),
            kind: "edit".to_string(),
            status: status.to_string(),
            content: None,
            raw_input: Some(raw_input.to_string()),
            raw_output: None,
            locations: None,
            meta: None,
            images: None,
            raw_input_is_model_authored: None,
        }
    }

    /// Which call a MiniMax Code permission request gates: the one unsettled
    /// call whose input is the request's.
    #[test]
    fn minimax_code_permission_resolves_to_the_unsettled_call_with_its_input() {
        let mut st = SessionState::new(
            "conn-test".to_string(),
            AgentType::MiniMaxCode,
            None,
            "win".to_string(),
            None,
        );
        let write = r#"{"path":"/w/a.txt","content":"x\n"}"#;
        st.apply_event(&minimax_tool_call("call_1", "completed", write));
        st.apply_event(&minimax_tool_call("call_2", "in_progress", write));
        st.apply_event(&minimax_tool_call(
            "call_3",
            "in_progress",
            r#"{"file_path":"/w/b.txt","old_string":"o","new_string":"n","_start_line":4}"#,
        ));
        let unmatched = BTreeSet::new();
        let call_2_matched = BTreeSet::from(["call_2".to_string()]);
        let gated =
            |st: &SessionState, matched: &BTreeSet<String>, input: Option<&serde_json::Value>| {
                minimax_gated_tool_call_id(&st.active_tool_calls, matched, input)
            };
        let write_input = serde_json::json!({"path": "/w/a.txt", "content": "x\n"});
        let edit_input =
            serde_json::json!({"file_path": "/w/b.txt", "old_string": "o", "new_string": "n"});
        let other_input = serde_json::json!({"path": "/w/c.txt", "content": "x\n"});

        // The settled call with the same input is not the one asking.
        assert_eq!(
            gated(&st, &unmatched, Some(&write_input)).as_deref(),
            Some("call_2")
        );
        // The `_start_line` codeg adds to a live edit does not hide it.
        assert_eq!(
            gated(&st, &unmatched, Some(&edit_input)).as_deref(),
            Some("call_3")
        );
        // Nothing in flight with that input, or no input at all: keep the
        // agent's own id.
        assert_eq!(gated(&st, &unmatched, Some(&other_input)), None);
        assert_eq!(gated(&st, &unmatched, None), None);
        // A call an earlier card was matched to is not asked about again.
        assert_eq!(gated(&st, &call_2_matched, Some(&write_input)), None);
        // Two identical calls in flight: no telling which one is asking,
        // unless one of them already had its card.
        st.apply_event(&minimax_tool_call("call_4", "in_progress", write));
        assert_eq!(gated(&st, &unmatched, Some(&write_input)), None);
        assert_eq!(
            gated(&st, &call_2_matched, Some(&write_input)).as_deref(),
            Some("call_4")
        );
    }

    /// The request can get here before the turn loop has applied the update
    /// that announces the call it gates; the lookup waits for that call (even
    /// past an earlier, already-matched call with the same input that still
    /// reads as in progress), and gives up, keeping the agent's id, when none
    /// ever shows up.
    #[tokio::test(start_paused = true)]
    async fn a_minimax_code_permission_waits_briefly_for_the_call_it_gates() {
        let state = Arc::new(RwLock::new(SessionState::new(
            "conn-test".to_string(),
            AgentType::MiniMaxCode,
            None,
            "win".to_string(),
            None,
        )));
        let raw = r#"{"path":"/outside/w.txt","content":"x\n"}"#;
        let input = serde_json::json!({"path": "/outside/w.txt", "content": "x\n"});
        let apply_later = |events: Vec<AcpEvent>| {
            let state = Arc::clone(&state);
            tokio::spawn(async move {
                tokio::time::sleep(std::time::Duration::from_millis(30)).await;
                let mut guard = state.write().await;
                for event in &events {
                    guard.apply_event(event);
                }
            })
        };

        let late = apply_later(vec![minimax_tool_call("call_9", "in_progress", raw)]);
        assert_eq!(
            claim_minimax_gated_tool_call_id(&state, Some(&input))
                .await
                .as_deref(),
            Some("call_9")
        );
        late.await.unwrap();

        // The same input again, for a newer call. call_9's card may have been
        // answered, withdrawn or drained, so no approval need be on record; its
        // completion and the newer call's announcement are both still queued.
        // call_9 still reads as in progress, but it is not the one asking.
        let late = apply_later(vec![
            minimax_tool_call("call_9", "completed", raw),
            minimax_tool_call("call_10", "in_progress", raw),
        ]);
        assert_eq!(
            claim_minimax_gated_tool_call_id(&state, Some(&input))
                .await
                .as_deref(),
            Some("call_10")
        );
        late.await.unwrap();

        let started = tokio::time::Instant::now();
        let other = serde_json::json!({"path": "/elsewhere.txt", "content": "y\n"});
        let gated = claim_minimax_gated_tool_call_id(&state, Some(&other)).await;
        assert_eq!(gated, None);
        assert!(started.elapsed() >= MINIMAX_GATED_CALL_WAIT);
        // A question asked through a permission card has no input to match.
        let started = tokio::time::Instant::now();
        assert_eq!(claim_minimax_gated_tool_call_id(&state, None).await, None);
        assert_eq!(started.elapsed(), std::time::Duration::ZERO);

        // The matches are per turn, like the calls they name.
        let mut guard = state.write().await;
        assert_eq!(
            guard.permission_matched_calls,
            BTreeSet::from(["call_9".to_string(), "call_10".to_string()])
        );
        guard.apply_event(&AcpEvent::TurnComplete {
            session_id: "s1".to_string(),
            stop_reason: "end_turn".to_string(),
            agent_type: "minimax_code".to_string(),
            mark_awaiting_reply: false,
            provider_turn_id: None,
            termination_source: None,
        });
        assert!(guard.permission_matched_calls.is_empty());
    }

    /// The card a MiniMax Code permission request raises, and the approval
