        append_npx_launch_args(
            &mut default_mode,
            AgentType::Grok,
            &["agent", "stdio"],
            None,
        );
        assert_eq!(
            default_mode,
            vec!["grok", "--no-auto-update", "agent", "stdio"]
        );

        let mut bypass = vec!["grok".to_string()];
