    #[tokio::test]
    async fn regression_bound_prompt_applies_terminal_air_failure_before_turn_complete() {
        let state = Arc::new(RwLock::new(SessionState::new(
            "conn-air-response".into(),
            AgentType::Codex,
            None,
            "test".into(),
            None,
        )));
        emit_with_state(
            &state,
            &EventEmitter::Noop,
            AcpEvent::SessionFailure {
                record: SessionFailureRecord {
                    id: "prompt-1:connection".into(),
                    revision: 1,
                    category: "connection".into(),
                    severity: "warning".into(),
                    title: "Reconnecting".into(),
                    details: None,
                    actions: Vec::new(),
                    resolved: false,
                },
            },
        )
        .await;
        let response_meta = meta_map(serde_json::json!({
            "jetbrains": {"air": {
                "version": 1,
                "sessionFailure": {
                    "id": "prompt-1:connection",
                    "revision": 2,
                    "category": "connection",
                    "severity": "error",
                    "title": "The connection to Codex was lost.",
                    "actions": ["new_session"]
                }
            }}
        }));
        let response = agent_client_protocol::schema::v1::PromptResponse::new(StopReason::EndTurn)
            .meta(response_meta);
        let mut suspension = None;
        let terminal_assoc = Arc::new(std::sync::Mutex::new(TerminalAssocFallback::new(false)));
        let terminal_runtime = Arc::new(TerminalRuntime::new(
            BTreeMap::new(),
            test_placeholder_terminal_shell().spec,
            adapter_for(AgentType::Codex),
        ));
        let perms: PendingPermissions =
            Arc::new(tokio::sync::Mutex::new(PermissionQueue::default()));
        let mut tracked_terminal_tool_calls = HashMap::new();
        let mut turn_timing_probe = None;
        let probe = TurnOutputProbe::new(0);
        let stderr_tail = StderrTail::new();

        let outcome = finalize_bound_prompt_response(
            Ok(response),
            &mut suspension,
            &state,
            &EventEmitter::Noop,
            "conn-air-response",
            &SessionId::new("session-air-response"),
            AgentType::Codex,
            false,
            &terminal_assoc,
            &mut tracked_terminal_tool_calls,
            &terminal_runtime,
            &perms,
            false,
            crate::acp_transcript::now_epoch_ms(),
            &mut turn_timing_probe,
            None,
            &probe,
            &stderr_tail,
            None,
        )
        .await
        .expect("bound prompt finalization");
        assert!(!outcome.status_restored_by_suspension);
        assert!(!outcome.disconnect_requested);

        let events = state
            .read()
            .await
            .recent_events_after(0)
            .expect("contiguous AIR response events");
        let failure_index = events
            .iter()
            .position(|event| {
                matches!(
                    &event.payload,
                    AcpEvent::SessionFailure { record }
                        if record.id == "prompt-1:connection" && record.revision == 2
                )
            })
            .expect("terminal response failure event");
        let turn_complete_index = events
            .iter()
            .position(|event| {
                matches!(
                    &event.payload,
                    AcpEvent::TurnComplete { stop_reason, .. } if stop_reason == "end_turn"
                )
            })
            .expect("clean wire stop reason remains the turn boundary");
        assert!(failure_index < turn_complete_index);
        assert!(!events
            .iter()
            .any(|event| matches!(event.payload, AcpEvent::Error { .. })));

        let state = state.read().await;
        let failure = state
            .session_failures
            .get("prompt-1:connection")
            .expect("terminal failure in session state");
        assert_eq!(failure.revision, 2);
        assert_eq!(failure.severity, "error");
        assert!(!failure.resolved);
    }

    #[tokio::test]
    async fn auth_required_prompt_rejection_keeps_the_session_addressable() {
        let state = Arc::new(RwLock::new(SessionState::new(
            "conn-auth-required".into(),
            AgentType::Cursor,
            None,
            "win-test".into(),
            None,
        )));
        {
            let mut session_state = state.write().await;
            session_state.turn_in_flight = true;
            session_state.active_turn_generation = Some(1);
        }
        let mut suspension = None;
        let terminal_assoc = Arc::new(std::sync::Mutex::new(TerminalAssocFallback::new(false)));
        let terminal_runtime = Arc::new(TerminalRuntime::new(
            BTreeMap::new(),
            test_placeholder_terminal_shell().spec,
            adapter_for(AgentType::Cursor),
        ));
        let perms: PendingPermissions =
            Arc::new(tokio::sync::Mutex::new(PermissionQueue::default()));
        let mut tracked_terminal_tool_calls = HashMap::new();
        let mut turn_timing_probe = None;
        let probe = TurnOutputProbe::new(0);
        let stderr_tail = StderrTail::new();

        let outcome = finalize_bound_prompt_response(
            Err(agent_client_protocol::Error::auth_required()),
            &mut suspension,
            &state,
            &EventEmitter::Noop,
            "conn-auth-required",
            &SessionId::new("session-auth-required"),
            AgentType::Cursor,
            false,
            &terminal_assoc,
            &mut tracked_terminal_tool_calls,
            &terminal_runtime,
            &perms,
            false,
            crate::acp_transcript::now_epoch_ms(),
            &mut turn_timing_probe,
            None,
            &probe,
            &stderr_tail,
            None,
        )
        .await
        .expect("auth rejection must not drop the connection");
        assert!(!outcome.disconnect_requested);
        assert!(!outcome.status_restored_by_suspension);

        let events = state
            .read()
            .await
            .recent_events_after(0)
            .expect("auth rejection events");
        assert!(events.iter().any(|event| matches!(
            &event.payload,
            AcpEvent::Error {
                code: Some(code),
                terminal: false,
                ..
            } if code == "turn_failed_auth_required"
        )));
        assert!(events.iter().any(|event| matches!(
            &event.payload,
            AcpEvent::TurnComplete { stop_reason, .. } if stop_reason == "auth_required"
        )));
    }

    fn subagent_launch_input(
        agent_type: AgentType,
        meta: Option<&serde_json::Map<String, serde_json::Value>>,
    ) -> Option<serde_json::Value> {
        match classify_codex_subagent_activity(agent_type, meta) {
            CodexSubagentActivity::Started { input, .. } => {
                Some(serde_json::from_str(&input).expect("valid JSON"))
            }
            _ => None,
        }
    }

    #[test]
    fn codex_subagent_launch_becomes_an_agent_capsule_input() {
        // codex 0.147 forwards nothing but this for a native sub-agent, so it is
        // the whole live signal: name from the path's last segment, thread id as
        // the card's badge, and no prompt (the task text is encrypted).
        let sub = meta_map(serde_json::json!({
            "codex": {
                "subagent": {
                    "threadId": "01a0098a-7e8a",
                    "path": "/root/pnpm_build",
                    "activity": "started",
                }
            }
        }));
        assert_eq!(
            subagent_launch_input(AgentType::Codex, Some(&sub)),
            Some(serde_json::json!({
                "subagent_type": "pnpm_build",
                "agent_id": "01a0098a-7e8a",
                // Says the card stands for the LAUNCH, so its "completed" is
                // not read as "the sub-agent finished" — the parser writes the
                // same key on reload.
                crate::parsers::codex::CODEX_SUBAGENT_LAUNCH_KEY: true,
            }))
        );
        // A trailing slash / empty path must not produce a nameless capsule, and
        // a missing thread id just drops the badge rather than the whole card.
        let odd = meta_map(serde_json::json!({
            "codex": { "subagent": { "path": "/", "activity": "started" } }
        }));
        assert_eq!(
            subagent_launch_input(AgentType::Codex, Some(&odd)),
            Some(serde_json::json!({
                "subagent_type": "subagent",
                crate::parsers::codex::CODEX_SUBAGENT_LAUNCH_KEY: true,
            }))
        );
    }

    #[test]
    fn codex_subagent_activity_classified_only_for_codex_subagent_meta() {
        let started = meta_map(serde_json::json!({
            "codex": { "subagent": { "threadId": "t1", "path": "/root/x", "activity": "started" } }
        }));
        // Only Codex is gated — the same meta never reshapes another agent's call.
        assert!(matches!(
            classify_codex_subagent_activity(AgentType::ClaudeCode, Some(&started)),
            CodexSubagentActivity::None
        ));
        // A mid-life marker stays dropped: it carries no content and would open
        // a second, indistinguishable capsule for the same sub-agent.
        let interacted = meta_map(serde_json::json!({
            "codex": { "subagent": { "threadId": "t1", "path": "/root/x", "activity": "interacted" } }
        }));
        assert!(matches!(
            classify_codex_subagent_activity(AgentType::Codex, Some(&interacted)),
            CodexSubagentActivity::Other
        ));
        // A terminal marker is not dropped — it is the only live signal that the
        // child stopped working, and it is routed onto the LAUNCH capsule (its
        // own `toolCallId` is a synthetic `subagent-completed-<uuid>` codeg has
        // never seen), keyed by the thread id.
        for kind in ["completed", "interrupted"] {
            let terminal = meta_map(serde_json::json!({
                "codex": { "subagent": { "threadId": "t1", "path": "/root/x", "activity": kind } }
            }));
            match classify_codex_subagent_activity(AgentType::Codex, Some(&terminal)) {
                CodexSubagentActivity::Terminal {
                    thread_id,
                    kind: got,
                } => {
                    assert_eq!(thread_id, "t1");
                    assert_eq!(got, kind);
                }
                other => panic!("{kind} should be terminal, got {other:?}"),
            }
            // Without a thread id there is no capsule to attribute it to, so it
            // degrades to the old drop rather than opening a stray card.
            let anonymous = meta_map(serde_json::json!({
                "codex": { "subagent": { "path": "/root/x", "activity": kind } }
            }));
            assert!(matches!(
                classify_codex_subagent_activity(AgentType::Codex, Some(&anonymous)),
                CodexSubagentActivity::Other
            ));
        }
        // Absent meta and sibling codex meta keys (goal / collaboration) are not
        // subagent activity and must render normally.
        assert!(matches!(
            classify_codex_subagent_activity(AgentType::Codex, None),
            CodexSubagentActivity::None
        ));
        let goal = meta_map(serde_json::json!({ "codex": { "goal": { "objective": "x" } } }));
        assert!(matches!(
            classify_codex_subagent_activity(AgentType::Codex, Some(&goal)),
            CodexSubagentActivity::None
        ));
        let collab = meta_map(serde_json::json!({
            "codex": { "collaboration": { "tool": "spawnAgent" } }
        }));
        assert!(matches!(
            classify_codex_subagent_activity(AgentType::Codex, Some(&collab)),
            CodexSubagentActivity::None
        ));
    }

    #[test]
    fn codex_subagent_terminal_state_is_added_to_the_launch_input() {
        // The outcome rides `rawInput`, not `_meta`: `upsert_tool_call` replaces
        // meta wholesale but parses and swaps in a fresh raw_input, so re-sending
        // the launch's own input plus one key is the only patch that cannot drop
        // what codex-acp already put on the card.
        let launch = serde_json::json!({
            "subagent_type": "history_limits",
            "agent_id": "01a07fc2-db62",
            crate::parsers::codex::CODEX_SUBAGENT_LAUNCH_KEY: true,
        })
        .to_string();
        let settled: serde_json::Value =
            serde_json::from_str(&codex_subagent_terminal_input(&launch, "completed"))
                .expect("valid JSON");
        assert_eq!(
            settled,
            serde_json::json!({
                "subagent_type": "history_limits",
                "agent_id": "01a07fc2-db62",
                crate::parsers::codex::CODEX_SUBAGENT_LAUNCH_KEY: true,
                // The parser stamps the same key on reload, so the card reads
                // identically live and after a refresh.
                crate::parsers::codex::CODEX_SUBAGENT_STATE_KEY: "completed",
            })
        );
        // A launch whose input never parsed still yields a usable card rather
        // than propagating the damage.
        let recovered: serde_json::Value =
            serde_json::from_str(&codex_subagent_terminal_input("not json", "interrupted"))
                .expect("valid JSON");
        assert_eq!(
            recovered,
            serde_json::json!({
                crate::parsers::codex::CODEX_SUBAGENT_STATE_KEY: "interrupted",
            })
        );
    }

    #[test]
    fn codex_plan_review_detected_only_for_codex_plan_review_meta() {
        // codex-acp #351: `_meta.codex.kind = "plan_review"` on the permission
        // REQUEST marks the Plan-mode review gate whose tool call was never
        // announced.
        let review = meta_map(serde_json::json!({
            "codex": { "kind": "plan_review", "planItemId": "item-7" }
        }));
        let is_review =
            |agent, id: &str, meta: Option<&serde_json::Map<String, serde_json::Value>>| {
                codex_plan_review_meta(agent, id, true, meta).is_some()
            };
        assert!(is_review(
            AgentType::Codex,
            "plan-review:item-7",
            Some(&review)
        ));
        // The legacy marker alone is enough — it is the 1.x identity.
        assert!(is_review(AgentType::Codex, "anything", Some(&review)));
        // Gated on Codex: an identical meta from another agent seeds nothing.
        assert!(!is_review(
            AgentType::ClaudeCode,
            "plan-review:item-7",
            Some(&review)
        ));
        // Ordinary permission requests carry no meta at all.
        assert!(!is_review(AgentType::Codex, "cmd-1", None));
        // Sibling `codex` keys and other `kind` values must not seed a card.
        let other_kind = meta_map(serde_json::json!({ "codex": { "kind": "mcp_tool_call" } }));
        assert!(!is_review(AgentType::Codex, "cmd-1", Some(&other_kind)));
        let sub = meta_map(serde_json::json!({ "codex": { "subagent": { "threadId": "t1" } } }));
        assert!(!is_review(AgentType::Codex, "cmd-1", Some(&sub)));
        // A non-string `kind` must not be coerced into a match.
        let numeric = meta_map(serde_json::json!({ "codex": { "kind": 1 } }));
        assert!(!is_review(AgentType::Codex, "cmd-1", Some(&numeric)));
    }

    #[test]
    fn codex_plan_review_is_recognised_by_id_once_the_marker_is_gone() {
        // codex-acp 2.0.0, recorded: the request carries NO `_meta` at all;
        // only `toolCallId: "plan-review:<planItemId>"` identifies the gate.
        let seeded = codex_plan_review_meta(AgentType::Codex, "plan-review:plan-2", true, None)
            .expect("the id identifies the gate");
        // The legacy marker is written onto the seeded card, which is what
        // the frontend names it by (`codexMarksPlanReview`).
        assert_eq!(
            serde_json::Value::Object(seeded),
            serde_json::json!({"codex": {"kind": "plan_review", "planItemId": "plan-2"}})
        );
        // A request `_meta` that says something else is kept beside it.
        let other = meta_map(serde_json::json!({ "jetbrains": { "air": { "version": 1 } } }));
        let seeded =
            codex_plan_review_meta(AgentType::Codex, "plan-review:p", true, Some(&other)).unwrap();
        assert_eq!(seeded["jetbrains"]["air"]["version"], 1);
        assert_eq!(seeded["codex"]["planItemId"], "p");
        assert!(codex_plan_review_meta(AgentType::Codex, "plan-review:", true, None).is_none());
        assert!(
            codex_plan_review_meta(AgentType::ClaudeCode, "plan-review:p", true, None).is_none()
        );
        // The id shape alone, on a request that is not the mode switch, is not
        // the review gate.
        assert!(codex_plan_review_meta(AgentType::Codex, "plan-review:p", false, None).is_none());
    }

    #[test]
    fn config_option_state_command_suppressed_only_for_codex_set_config_action() {
        // codex-acp #293: `/plan` is a config-option state toggle (rendered as the
        // `collaboration_mode` selector), not an invokable slash command.
        let plan = meta_map(serde_json::json!({
            "commandAction": {
                "kind": "setConfigOption",
                "configId": "collaboration_mode",
                "value": "plan",
                "resetValue": "default",
                "presentation": "state"
            }
        }));
        assert!(is_config_option_state_command(
            AgentType::Codex,
            Some(&plan)
        ));
        // Gated on Codex — the same meta never suppresses another agent's command.
        assert!(!is_config_option_state_command(
            AgentType::ClaudeCode,
            Some(&plan)
        ));
        // `/goal` uses a `prefixPrompt` action (takes an objective argument) → a
        // real command, kept.
        let goal = meta_map(serde_json::json!({
            "commandAction": { "kind": "prefixPrompt", "presentation": "state" }
        }));
        assert!(!is_config_option_state_command(
            AgentType::Codex,
            Some(&goal)
        ));
        // codex-acp 2.0.0 sends the action under `_meta.jetbrains.air` only
        // (recorded) — the same toggle, suppressed the same way.
        let air_plan = meta_map(serde_json::json!({"jetbrains": {"air": {
            "version": 1,
            "commandAction": {
                "kind": "setConfigOption",
                "configId": "collaboration_mode",
                "value": "plan",
                "resetValue": "default",
                "presentation": "state"
            }
        }}}));
        assert!(is_config_option_state_command(
            AgentType::Codex,
            Some(&air_plan)
        ));
        let air_goal = meta_map(serde_json::json!({"jetbrains": {"air": {
            "version": 1,
            "commandAction": { "kind": "prefixPrompt", "presentation": "state" }
        }}}));
        assert!(!is_config_option_state_command(
            AgentType::Codex,
            Some(&air_goal)
        ));
        // Ordinary commands (no `commandAction`) and absent meta are kept.
        assert!(!is_config_option_state_command(AgentType::Codex, None));
        let plain = meta_map(serde_json::json!({ "somethingElse": true }));
        assert!(!is_config_option_state_command(
            AgentType::Codex,
            Some(&plain)
        ));
    }

    /// Commands as claude-agent-acp 0.99.1 sent them to codeg's capabilities
    /// (recorded live; the home directory renamed), in one of two lists.
    /// `before_read`: the list `session/new` sends, which marks only the skills
    /// whose `SKILL.md` the adapter finds under the cwd or the home directory.
    /// Otherwise the list it sends again once Claude Code's own skill list has
    /// been read (#1473), which marks the plugin and the bundled skills too.
    fn claude_0991_commands(
        before_read: bool,
    ) -> Vec<agent_client_protocol::schema::v1::AvailableCommand> {
        let skill = |path: Option<&str>| match path {
            Some(path) => serde_json::json!({"jetbrains": {"air": {
                "version": 1, "kind": "skill", "skillPath": path,
            }}}),
            None => serde_json::json!({"jetbrains": {"air": {"version": 1, "kind": "skill"}}}),
        };
        let mut commands = vec![
            serde_json::json!({"name": "user-skill", "description": "User skill probe (user)", "input": null,
                "_meta": skill(Some("/home/u/.claude/skills/user-skill/SKILL.md"))}),
            serde_json::json!({"name": "prompt-cmd", "description": "Prompt command probe (project)", "input": null}),
            serde_json::json!({"name": "plug:pskill", "description": "(plug) Plugin skill probe", "input": null}),
            serde_json::json!({"name": "simplify", "description": "Review the changed code", "input": {"hint": "[<target>]"}}),
            serde_json::json!({"name": "compact", "description": "Free up context by summarizing the conversation so far",
                "input": {"hint": "<optional custom summarization instructions>"}}),
            serde_json::json!({"name": "mcp", "description": "Show the MCP servers and their status, or reconnect, enable, or disable a server",
                "input": {"hint": "[reconnect|enable|disable [<server>|all]]"}}),
        ];
        if !before_read {
            commands[2]["_meta"] = skill(Some("/home/u/plugins/plug/skills/pskill/SKILL.md"));
            commands[3]["_meta"] = skill(None);
        }
        serde_json::from_value(serde_json::Value::Array(commands)).expect("ACP commands")
    }

    /// The skill marks each listed command carries, as `(name, skill, path)`.
    fn skill_marks(commands: &[AvailableCommandInfo]) -> Vec<(&str, bool, Option<&str>)> {
        commands
            .iter()
            .map(|c| (c.name.as_str(), c.skill, c.skill_path.as_deref()))
            .collect()
    }

    #[test]
    fn claude_skill_commands_carry_the_air_skill_mark() {
        let read = available_command_infos(AgentType::ClaudeCode, &claude_0991_commands(false));
        assert_eq!(
            skill_marks(&read),
            vec![
                (
                    "user-skill",
                    true,
                    Some("/home/u/.claude/skills/user-skill/SKILL.md")
                ),
                ("prompt-cmd", false, None),
                (
                    "plug:pskill",
                    true,
                    Some("/home/u/plugins/plug/skills/pskill/SKILL.md")
                ),
                // Bundled with the CLI: a skill without a file.
                ("simplify", true, None),
                ("compact", false, None),
                ("mcp", false, None),
            ]
        );
        // The mark leaves the rest of the command as it was.
        assert_eq!(read[3].description, "Review the changed code");
        assert_eq!(read[3].input_hint.as_deref(), Some("[<target>]"));

        // Before the read only the skill found on disk is marked.
        let first = available_command_infos(AgentType::ClaudeCode, &claude_0991_commands(true));
        assert_eq!(
            skill_marks(&first),
            vec![
                (
                    "user-skill",
                    true,
                    Some("/home/u/.claude/skills/user-skill/SKILL.md")
                ),
                ("prompt-cmd", false, None),
                ("plug:pskill", false, None),
                ("simplify", false, None),
                ("compact", false, None),
                ("mcp", false, None),
            ]
        );
    }

    /// A command nothing marks goes to the frontend exactly as before the
    /// marks existed (no `skill` / `skill_path` keys), so every other agent's
    /// list and every snapshot is unchanged; a marked one adds the two keys.
    #[test]
    fn skill_marks_stay_off_the_wire_for_unmarked_commands() {
        let read = available_command_infos(AgentType::ClaudeCode, &claude_0991_commands(false));
        assert_eq!(
            serde_json::to_value(&read[4]).unwrap(),
            serde_json::json!({
                "name": "compact",
                "description": "Free up context by summarizing the conversation so far",
                "input_hint": "<optional custom summarization instructions>",
            })
        );
        assert_eq!(
            serde_json::to_value(&read[2]).unwrap(),
            serde_json::json!({
                "name": "plug:pskill",
                "description": "(plug) Plugin skill probe",
                "input_hint": null,
                "skill": true,
                "skill_path": "/home/u/plugins/plug/skills/pskill/SKILL.md",
            })
        );
        assert_eq!(
            serde_json::to_value(&read[3]).unwrap()["skill"],
            serde_json::json!(true)
        );
        assert!(serde_json::to_value(&read[3])
            .unwrap()
            .get("skill_path")
            .is_none());
        // A stored list from before the marks reads back unmarked.
        let old: AvailableCommandInfo = serde_json::from_value(serde_json::json!({
            "name": "compact", "description": "", "input_hint": null,
        }))
        .unwrap();
        assert!(!old.skill);
        assert_eq!(old.skill_path, None);
    }

    #[test]
    fn air_command_skill_reads_only_a_versioned_skill_kind() {
        let air =
            |value: serde_json::Value| meta_map(serde_json::json!({"jetbrains": {"air": value}}));
        assert_eq!(
            air_command_skill(Some(&air(serde_json::json!({
                "version": 1, "kind": "skill", "skillPath": " /p/SKILL.md ",
            })))),
            Some(Some("/p/SKILL.md".to_string()))
        );
        // A blank path is no path.
        assert_eq!(
            air_command_skill(Some(&air(serde_json::json!({
                "version": 1, "kind": "skill", "skillPath": "  ",
            })))),
            Some(None)
        );
        // No kind: codex-acp's `$skill` commands carry the path alone.
        assert_eq!(
            air_command_skill(Some(&air(serde_json::json!({
                "version": 1, "skillPath": "/workspace/.agents/skills/build/SKILL.md",
            })))),
            None
        );
        // Another kind, an envelope without a version or below 1, the key
        // outside the AIR namespace, and no `_meta` at all.
        assert_eq!(
            air_command_skill(Some(&air(
                serde_json::json!({"version": 1, "kind": "prompt"})
            ))),
            None
        );
        assert_eq!(
            air_command_skill(Some(&air(serde_json::json!({"kind": "skill"})))),
            None
        );
        assert_eq!(
            air_command_skill(Some(&air(
                serde_json::json!({"version": 0, "kind": "skill"})
            ))),
            None
        );
        assert_eq!(
            air_command_skill(Some(&meta_map(serde_json::json!({"kind": "skill"})))),
            None
        );
        assert_eq!(air_command_skill(None), None);
    }

    /// The first of two commands sharing a name is the one kept, mark and all,
    /// as it was before the marks.
    #[test]
    fn a_duplicate_command_name_keeps_the_first_entry_and_its_mark() {
        let commands: Vec<agent_client_protocol::schema::v1::AvailableCommand> =
            serde_json::from_value(serde_json::json!([
                {"name": "deploy", "description": "project", "input": null,
                    "_meta": {"jetbrains": {"air": {"version": 1, "kind": "skill", "skillPath": "/w/.claude/skills/deploy/SKILL.md"}}}},
                {"name": "deploy", "description": "user", "input": null},
            ]))
            .unwrap();
        assert_eq!(
            skill_marks(&available_command_infos(AgentType::ClaudeCode, &commands)),
            vec![("deploy", true, Some("/w/.claude/skills/deploy/SKILL.md"))]
        );
    }

    /// OpenCode 2.2.5's list as it sent it to codeg's capabilities, plus a
    /// `steer`. Only ZCode leaves any of them out, the commands codeg drives
    /// itself; OpenCode lists its `goal` like every other agent, though over
    /// ACP it does not work yet (see the OpenCode entry in `acp::registry`).
    #[test]
    fn opencode_lists_goal_and_zcode_leaves_its_own_commands_out() {
        let commands: Vec<agent_client_protocol::schema::v1::AvailableCommand> =
            serde_json::from_value(serde_json::json!([
                {"name": "init", "description": "guided AGENTS.md setup", "input": null},
                {"name": "review", "description": "review changes [commit|branch|pr], defaults to uncommitted", "input": null},
                {"name": "goal", "description": "keep working until an objective is met [pause|resume|clear]", "input": null},
                {"name": "compact", "description": "Compact the session", "input": null},
                {"name": "steer", "description": "steer the running turn", "input": null},
            ]))
            .unwrap();
        let names = |agent_type| {
            available_command_infos(agent_type, &commands)
                .into_iter()
                .map(|command| command.name)
                .collect::<Vec<_>>()
        };
        assert_eq!(names(AgentType::ZCode), ["init", "review", "compact"]);
        for agent_type in [
            AgentType::OpenCode,
            AgentType::ClaudeCode,
            AgentType::Codex,
            AgentType::KimiCode,
        ] {
            assert_eq!(
                names(agent_type),
                ["init", "review", "goal", "compact", "steer"],
                "{agent_type:?}"
            );
        }
    }

    #[test]
    fn goal_control_action_roundtrips_codex_wire_values() {
        // codex-acp #293: `_codex/session/goal_control` expects lowercase
        // "pause" / "clear" on the wire, and the same strings arrive from the
        // tauri command / HTTP endpoint — both directions must match exactly.
        assert_eq!(
            serde_json::to_value(GoalControlAction::Pause).unwrap(),
            serde_json::json!("pause")
        );
        assert_eq!(
            serde_json::to_value(GoalControlAction::Clear).unwrap(),
            serde_json::json!("clear")
        );
        assert_eq!(
            serde_json::from_value::<GoalControlAction>(serde_json::json!("pause")).unwrap(),
            GoalControlAction::Pause
        );
        assert_eq!(
            serde_json::from_value::<GoalControlAction>(serde_json::json!("clear")).unwrap(),
            GoalControlAction::Clear
        );
    }

    // --- native steering: capability synthesis + wire helpers -------------
    // (reuses the shared `meta_map` test helper defined above)

    #[test]
    fn init_advertises_steering_reads_the_top_level_meta_flag() {
        let on = meta_map(serde_json::json!({"steering": {"supported": true}}));
        assert!(init_advertises_steering(Some(&on)));

        let off = meta_map(serde_json::json!({"steering": {"supported": false}}));
        assert!(!init_advertises_steering(Some(&off)));

        // Wrong nesting (e.g. another convention's namespace) must not count.
        let nested = meta_map(serde_json::json!({"symposium": {"steering": {"supported": true}}}));
        assert!(!init_advertises_steering(Some(&nested)));

        // Non-bool / absent → false.
        let stringly = meta_map(serde_json::json!({"steering": {"supported": "true"}}));
        assert!(!init_advertises_steering(Some(&stringly)));
        assert!(!init_advertises_steering(None));
    }

    /// claude-agent-acp 0.92.0's `initialize` answer, as its own scenario harness
    /// records it for codeg's exact `clientCapabilities`: ACP SDK 1.9.0 adds the
    /// unstable `sessionCapabilities.systemPrompt`, which this schema crate does
    /// not know. The typed response must still parse, with every capability
    /// codeg reads beside it intact — a failed parse here would end every
    /// Claude connection at its handshake.
    #[test]
    fn claude_0920_initialize_response_parses_past_its_system_prompt_capability() {
        let wire = serde_json::json!({
            "_meta": {
                "jetbrains": {"air": {
                    "capabilities": ["sessionFailure", "agentFileChangeReport", "nativeSubagentSessions",
                        "asyncTasks", "customInstructions", "recommendedValue", "diffPatch", "planFile"],
                    "goal": {"actions": ["set", "clear"], "controlMethod": "_session/goal", "version": 1},
                    "version": 1
                }},
                "steering": {"supported": true}
            },
            "agentCapabilities": {
                "_meta": {"authStatus": {}, "claudeCode": {"promptQueueing": true}},
                "auth": {"logout": {}},
                "loadSession": true,
                "mcpCapabilities": {"http": true, "sse": true},
                "promptCapabilities": {"embeddedContext": true, "image": true},
                "providers": {},
                "sessionCapabilities": {
                    "additionalDirectories": {}, "close": {}, "delete": {}, "fork": {}, "list": {},
                    "resume": {}, "subagents": {},
                    "systemPrompt": {"mode": {"override": {}}}
                }
            },
            "agentInfo": {"name": "@agentclientprotocol/claude-agent-acp", "title": "Claude Agent", "version": "0.92.0"},
            "authMethods": [],
            "protocolVersion": 1
        });
        let response: agent_client_protocol::schema::v1::InitializeResponse =
            serde_json::from_value(wire).expect("0.92.0 initialize parses");
        let caps = &response.agent_capabilities;
        assert!(caps.load_session);
        assert!(caps.session_capabilities.resume.is_some());
        assert!(caps.session_capabilities.close.is_some());
        assert!(caps.session_capabilities.fork.is_some());
        assert!(caps.prompt_capabilities.image);
        assert!(init_advertises_steering(response.meta.as_ref()));
        assert!(init_advertises_goal(response.meta.as_ref()));
        assert_eq!(
            response.agent_info.as_ref().map(|info| info.name.as_str()),
            Some(crate::acp::registry::CLAUDE_AGENT_ACP_PACKAGE)
        );
    }

    /// codex-acp 2.3.0's `initialize` answer to codeg's exact
    /// `clientCapabilities`, recorded live: it adds the unstable
    /// `sessionCapabilities.systemPrompt` (#653) and `mcpCapabilities.acp`,
    /// neither of which this schema crate knows, and still answers a v1
    /// request with `protocolVersion: 1` although it speaks ACP v2 to a v2
    /// client (#620). A failed parse here would end every Codex connection at
    /// its handshake.
    #[test]
    fn codex_230_initialize_response_parses_past_its_new_capabilities() {
        let wire = serde_json::json!({
            "protocolVersion": 1,
            "agentInfo": {"name": "@agentclientprotocol/codex-acp", "title": "Codex", "version": "2.3.0"},
            "agentCapabilities": {
                "auth": {"logout": {}},
                "providers": {},
                "loadSession": true,
                "promptCapabilities": {"embeddedContext": true, "image": true},
                "sessionCapabilities": {
                    "resume": {}, "list": {}, "close": {}, "delete": {}, "fork": {},
                    "additionalDirectories": {}, "subagents": {}, "systemPrompt": {}
                },
                "mcpCapabilities": {"acp": false, "http": true, "sse": false},
                "_meta": {"authStatus": {}}
            },
            "authMethods": [
                {"id": "api-key", "name": "API Key", "description": "Use an API key to authenticate",
                    "_meta": {"api-key": {"provider": "openai"}}},
                {"id": "chat-gpt", "name": "ChatGPT", "description": "Use ChatGPT to authenticate"}
            ],
            "_meta": {
                "steering": {"supported": true},
                "jetbrains": {"air": {
                    "version": 1,
                    "goal": {"version": 1, "controlMethod": "_session/goal",
                        "actions": ["set", "pause", "resume", "clear"]},
                    "capabilities": ["sessionFailure", "diffPatch", "agentFileChangeReport",
                        "customInstructions", "nativeSubagentSessions", "asyncTasks",
                        "recommendedValue", "rawInputRendering", "planContentDelta", "codexHooks"]
                }}
            }
        });
        let response: agent_client_protocol::schema::v1::InitializeResponse =
            serde_json::from_value(wire).expect("2.3.0 initialize parses");
        assert_eq!(response.protocol_version, ProtocolVersion::V1);
        let caps = &response.agent_capabilities;
        assert!(caps.load_session);
        assert!(caps.session_capabilities.resume.is_some());
        assert!(caps.session_capabilities.close.is_some());
        assert!(caps.session_capabilities.fork.is_some());
        assert!(caps.prompt_capabilities.image);
        assert!(caps.mcp_capabilities.http);
        assert!(init_advertises_steering(response.meta.as_ref()));
        assert!(init_advertises_goal(response.meta.as_ref()));
        assert_eq!(
            response
                .agent_info
                .as_ref()
                .map(|info| info.version.as_str()),
            Some("2.3.0")
        );
    }

    /// zcode-acp-server 0.82.0's `initialize` answer to codeg's exact
    /// `clientCapabilities`, recorded against a stand-in backend: from 0.81.0
    /// the bridge advertises the steering extension, with a `timings` list of
    /// its own. The answer must still parse, and the advertisement alone must
    /// not move ZCode off the pull channel: codeg has no steering floor for
    /// it, and the bridge's `_session/steering` still starts a turn of its own
    /// when the running one ends just before the backend takes the text.
    #[test]
    fn zcode_0820_initialize_advertises_steering_but_keeps_the_pull_channel() {
        let wire = serde_json::json!({
            "_meta": {"steering": {"supported": true, "timings": ["now", "next"]}},
            "agentCapabilities": {
                "_meta": {"zcode": {"fs": true, "turnState": ["$/zcode/turnState", "_zcode/turnState"]}},
                "loadSession": true,
                "mcpCapabilities": {"http": true, "sse": false},
                "promptCapabilities": {"audio": false, "embeddedContext": true, "image": true},
                "sessionCapabilities": {"fork": {}, "list": {}, "resume": {}}
            },
            "agentInfo": {"name": "zcode-acp-server", "title": "ZCode", "version": "0.82.0"},
            "authMethods": [{
                "description": "Reads the GLM API key from the ZCode desktop app's credential files (~/.zcode/v2) or a saved zcode-acp account. No editor-side credentials required.",
                "id": "zcode-credentials",
                "name": "ZCode built-in credentials"
            }],
            "protocolVersion": 1
        });
        let response: agent_client_protocol::schema::v1::InitializeResponse =
            serde_json::from_value(wire).expect("0.82.0 initialize parses");
        assert_eq!(response.protocol_version, ProtocolVersion::V1);
        assert!(response.agent_capabilities.load_session);
        assert!(init_advertises_steering(response.meta.as_ref()));
        assert!(!synthesize_native_steering(
            AgentType::ZCode,
            response.meta.as_ref(),
            response.agent_info.as_ref(),
        ));
    }

    #[test]
    fn init_advertises_goal_requires_integer_version_at_least_1() {
        // The real advertisements: codex-acp 1.2.0+ / claude-agent-acp 0.66.0+.
        let codex = meta_map(serde_json::json!({"goal": {
            "version": 1,
            "controlMethod": "_session/goal",
            "actions": ["set", "pause", "resume", "clear"],
        }}));
        assert!(init_advertises_goal(Some(&codex)));
        // Future versions must keep selecting the neutral channel.
        let v2 = meta_map(serde_json::json!({"goal": {"version": 2}}));
        assert!(init_advertises_goal(Some(&v2)));
        // claude-agent-acp 0.82.0 / codex-acp 2.0.0 advertise it under AIR
        // only (recorded `initialize` responses).
        let air = meta_map(serde_json::json!({"jetbrains": {"air": {
            "version": 1,
            "capabilities": ["sessionFailure"],
            "goal": {"version": 1, "controlMethod": "_session/goal", "actions": ["set", "clear"]},
        }}}));
        assert!(init_advertises_goal(Some(&air)));
        assert_eq!(
            goal_advertised_control(Some(&air)),
            Some((
                "_session/goal".to_string(),
                vec!["set".to_string(), "clear".to_string()]
            ))
        );

        // Fail closed onto the legacy channel: sub-1, non-integer, stringly,
        // absent, or wrongly-shaped advertisements.
        for bad in [
            serde_json::json!({"goal": {"version": 0}}),
            serde_json::json!({"goal": {"version": 1.5}}),
            serde_json::json!({"goal": {"version": "1"}}),
            serde_json::json!({"goal": {}}),
            serde_json::json!({"goal": true}),
            serde_json::json!({"steering": {"supported": true}}),
        ] {
            let meta = meta_map(bad);
            assert!(!init_advertises_goal(Some(&meta)));
        }
        assert!(!init_advertises_goal(None));
    }

    #[test]
    fn session_info_goal_value_reads_exactly_one_channel() {
        // A transitional adapter double-publishing the same transition through
        // both namespaces (even across separate updates) must yield the goal
        // from exactly ONE channel — the one pinned at initialize.
        let both = meta_map(serde_json::json!({
            "goal": {"objective": "neutral", "status": "active"},
            "codex": {"goal": {"objective": "legacy", "status": "active"}},
        }));
        let neutral = session_info_goal_value(true, Some(&both)).expect("neutral value");
        assert_eq!(
            neutral.get("objective").and_then(|v| v.as_str()),
            Some("neutral")
        );
        let legacy = session_info_goal_value(false, Some(&both)).expect("legacy value");
        assert_eq!(
            legacy.get("objective").and_then(|v| v.as_str()),
            Some("legacy")
        );

        // Neutral-pinned connections ignore a legacy-only update (and vice
        // versa) — the two updates of a double-publish collapse to one marker.
        let legacy_only = meta_map(
            serde_json::json!({"codex": {"goal": {"objective": "legacy", "status": "active"}}}),
        );
        assert!(session_info_goal_value(true, Some(&legacy_only)).is_none());
        let neutral_only =
            meta_map(serde_json::json!({"goal": {"objective": "neutral", "status": "active"}}));
        assert!(session_info_goal_value(false, Some(&neutral_only)).is_none());

        // `goal: null` IS a value (the clear signal), not an absent key.
        let cleared = meta_map(serde_json::json!({"goal": null}));
        assert!(matches!(
            session_info_goal_value(true, Some(&cleared)),
            Some(v) if v.is_null()
        ));
        assert!(session_info_goal_value(false, Some(&cleared)).is_none());
        assert!(session_info_goal_value(true, None).is_none());

        // claude-agent-acp 0.82.0 / codex-acp 2.0.0 publish the snapshot —
        // and its clear — under `_meta.jetbrains.air.goal` (recorded).
        let air = meta_map(serde_json::json!({"jetbrains": {"air": {
            "version": 1,
            "goal": {"objective": "Ship it", "status": "active"},
        }}}));
        assert_eq!(
            session_info_goal_value(true, Some(&air))
                .and_then(|g| g.get("objective"))
                .and_then(|v| v.as_str()),
            Some("Ship it")
        );
        assert!(session_info_goal_value(false, Some(&air)).is_none());
        let air_cleared =
            meta_map(serde_json::json!({"jetbrains": {"air": {"version": 1, "goal": null}}}));
        assert!(matches!(
            session_info_goal_value(true, Some(&air_cleared)),
            Some(v) if v.is_null()
        ));
        // An AIR envelope that carries something else is no goal update.
        let failure = meta_map(serde_json::json!({"jetbrains": {"air": {
            "version": 1, "sessionFailure": {"id": "x", "revision": 1}
        }}}));
        assert!(session_info_goal_value(true, Some(&failure)).is_none());
    }

    // --- predicted follow-up prompt (`_meta.promptSuggestions`) ------------

    #[test]
    fn prompt_suggestion_update_reads_the_offer_the_clear_and_nothing_else() {
        let read = |meta: serde_json::Value| {
            prompt_suggestion_update(AgentType::ClaudeCode, Some(&meta_map(meta)))
        };
        // claude-agent-acp 0.92.0's two frames: an offer, and the clear it
        // sends when the next prompt arrives.
        assert_eq!(
            read(
                serde_json::json!({"promptSuggestions": {"suggestions": [{"text": "Run the tests"}]}})
            ),
            Some(Some("Run the tests".to_string()))
        );
        assert_eq!(
            read(serde_json::json!({"promptSuggestions": {"suggestions": []}})),
            Some(None)
        );
        // The first non-blank text is the one offered, trimmed.
        assert_eq!(
            read(serde_json::json!({"promptSuggestions": {"suggestions": [
                {"text": "   "}, {"other": 1}, {"text": "  commit this \n"}, {"text": "push it"}
            ]}})),
            Some(Some("commit this".to_string()))
        );
        // Only blank texts withdraw the offer rather than showing an empty hint.
        assert_eq!(
            read(serde_json::json!({"promptSuggestions": {"suggestions": [{"text": " "}]}})),
            Some(None)
        );
        // Anything else leaves the held one as it is: no key, an unreadable
        // shape, or a goal/title-only update.
        assert_eq!(read(serde_json::json!({"goal": {"version": 1}})), None);
        assert_eq!(read(serde_json::json!({"promptSuggestions": null})), None);
        assert_eq!(
            read(serde_json::json!({"promptSuggestions": {"suggestions": "x"}})),
            None
        );
        assert_eq!(read(serde_json::json!({"promptSuggestions": {}})), None);
        assert_eq!(prompt_suggestion_update(AgentType::ClaudeCode, None), None);
    }

    /// Read only from the two adapters codeg declares AIR to, the only ones the
    /// key is sent to: an unnamespaced key from anyone else is not taken on trust.
    #[test]
    fn prompt_suggestion_update_is_read_from_the_air_adapters_only() {
        let offer = meta_map(serde_json::json!({
            "promptSuggestions": {"suggestions": [{"text": "Run the tests"}]}
        }));
        assert!(prompt_suggestion_update(AgentType::Codex, Some(&offer)).is_some());
        for agent_type in [AgentType::CodeBuddy, AgentType::Grok, AgentType::OpenCode] {
            assert_eq!(
                prompt_suggestion_update(agent_type, Some(&offer)),
                None,
                "{agent_type:?}"
            );
        }
    }

    /// Drive one `session_info_update` with this `_meta` through
    /// `emit_conversation_update`, as the idle loop does between turns.
    async fn drive_session_info_meta(
        state: &Arc<RwLock<SessionState>>,
        agent_type: AgentType,
        meta: serde_json::Value,
    ) {
        let update: SessionUpdate = serde_json::from_value(serde_json::json!({
            "sessionUpdate": "session_info_update",
            "_meta": meta,
        }))
        .expect("valid session_info_update wire shape");
        let mut cache = ToolCallOutputCache::default();
        let mut cb = CodeBuddyLiveState::default();
        emit_conversation_update(
            state,
            &EventEmitter::Noop,
            agent_type,
            update,
            None,
            &mut cache,
            &mut cb,
            None,
        )
        .await;
    }

    /// The offer and the clear each become a `PromptSuggestion` event, which the
    /// session state keeps for the snapshot; an update without the key (a goal,
    /// a title) emits none and leaves the held offer alone.
    #[tokio::test]
    async fn session_info_update_offers_and_withdraws_the_predicted_prompt() {
        let state = Arc::new(RwLock::new(SessionState::new(
            "conn-suggest".to_string(),
            AgentType::ClaudeCode,
            None,
            "win".to_string(),
            None,
        )));
        let suggestions = |state: &SessionState| -> Vec<Option<String>> {
            state
                .recent_events_after(0)
                .unwrap_or_default()
                .iter()
                .filter_map(|e| match &e.payload {
                    AcpEvent::PromptSuggestion { text } => Some(text.clone()),
                    _ => None,
                })
                .collect()
        };

        drive_session_info_meta(
            &state,
            AgentType::ClaudeCode,
            serde_json::json!({"promptSuggestions": {"suggestions": [{"text": "Run the tests"}]}}),
        )
        .await;
        assert_eq!(
            state.read().await.prompt_suggestion.as_deref(),
            Some("Run the tests")
        );

        drive_session_info_meta(
            &state,
            AgentType::ClaudeCode,
            serde_json::json!({"jetbrains": {"air": {"version": 1}}}),
        )
        .await;
        assert_eq!(
            state.read().await.prompt_suggestion.as_deref(),
            Some("Run the tests"),
            "an update without the key keeps the offer"
        );

        drive_session_info_meta(
            &state,
            AgentType::ClaudeCode,
            serde_json::json!({"promptSuggestions": {"suggestions": []}}),
        )
        .await;
        assert_eq!(state.read().await.prompt_suggestion, None);
        assert_eq!(
            suggestions(&*state.read().await),
            vec![Some("Run the tests".to_string()), None]
        );
    }

    // --- Claude Code's Remote Control (claude-agent-acp 0.93.0) ------------

    /// The success reply of claude-agent-acp 0.93.0's `runRemoteControlCommand`,
    /// verbatim.
    fn remote_control_active_reply(url: &str) -> String {
        format!(
            "Remote Control is active. Continue this session from claude.ai/code or the \
             Claude mobile app:\n\n{url}\n\nRun /remote-control off to disconnect."
        )
    }

    fn text_blocks(texts: &[&str]) -> Vec<ContentBlock> {
        texts
            .iter()
            .map(|text| ContentBlock::Text(TextContent::new(*text)))
            .collect()
    }

    /// The prompts the adapter answers itself, read with its own
    /// `parseRemoteControlCommand` rules: one text block, JavaScript `trim`
    /// and `\s`, the name exact, `off` in any case.
    #[test]
    fn remote_control_command_reads_what_the_adapter_parses() {
        use RemoteControlCommand::{Connect, Disconnect};
        for (text, want) in [
            ("/remote-control", Some(Connect)),
            ("  /remote-control\n", Some(Connect)),
            ("/remote-control My laptop session", Some(Connect)),
            ("/remote-control\toff", Some(Disconnect)),
            ("/remote-control OFF", Some(Disconnect)),
            ("  /remote-control   Off  ", Some(Disconnect)),
            // JavaScript's whitespace, not Rust's: U+FEFF trims, U+0085 doesn't.
            ("\u{FEFF}/remote-control off\u{FEFF}", Some(Disconnect)),
            ("/remote-control\u{3000}off", Some(Disconnect)),
            ("/remote-control\u{85}off", None),
            ("/remote-control off now", Some(Connect)),
            ("/remote-controller", None),
            ("/Remote-Control", None),
            ("please /remote-control", None),
            ("/rc", None),
        ] {
            assert_eq!(
                remote_control_command(AgentType::ClaudeCode, &text_blocks(&[text])),
                want,
                "{text:?}"
            );
        }
        // Anything beside the one text block goes to Claude Code instead.
        assert_eq!(
            remote_control_command(
                AgentType::ClaudeCode,
                &text_blocks(&["/remote-control", "extra"])
            ),
            None
        );
        assert_eq!(remote_control_command(AgentType::ClaudeCode, &[]), None);
        // Only claude-agent-acp has the command.
        assert_eq!(
            remote_control_command(AgentType::Codex, &text_blocks(&["/remote-control"])),
            None
        );
    }

    /// The adapter's five replies, verbatim, and what each says Remote Control
    /// is now; any other text says nothing.
    #[test]
    fn remote_control_reply_reads_the_adapters_five_replies() {
        use RemoteControlCommand::{Connect, Disconnect};
        let url = "https://claude.ai/code/session_01ABCdef";
        assert_eq!(
            remote_control_reply(Connect, &remote_control_active_reply(url)),
            Some(Some(RemoteControlInfo {
                session_url: Some(url.to_string())
            }))
        );
        assert_eq!(
            remote_control_reply(
                Connect,
                "Remote Control is active, but Claude Code did not return a session URL."
            ),
            Some(Some(RemoteControlInfo { session_url: None }))
        );
        // Measured through a gateway (0.93.0, CLI 2.1.300).
        assert_eq!(
            remote_control_reply(
                Connect,
                "Could not start Remote Control: Remote Control is only available when using \
                 Claude via api.anthropic.com. ANTHROPIC_BASE_URL is set and does not point at \
                 api.anthropic.com, so this session is using a custom endpoint — unset it (or \
                 run in a shell without it) to use Remote Control."
            ),
            Some(None)
        );
        assert_eq!(
            remote_control_reply(
                Disconnect,
                "Remote Control is off. Run /remote-control to reconnect."
            ),
            Some(None)
        );
        assert_eq!(
            remote_control_reply(Disconnect, "Could not stop Remote Control: offline"),
            None,
            "a stop that failed leaves it as it was"
        );
        // Claude Code's own answer to a command the adapter left to it, and
        // replies to the other command, say nothing.
        assert_eq!(
            remote_control_reply(
                Connect,
                "/remote-control isn't available in this environment."
            ),
            None
        );
        assert_eq!(
            remote_control_reply(Disconnect, &remote_control_active_reply(url)),
            None
        );
        assert_eq!(
            remote_control_reply(
                Connect,
                "Remote Control is off. Run /remote-control to reconnect."
            ),
            None
        );
    }

    #[test]
    fn remote_control_session_url_takes_the_first_https_url_as_written() {
        assert_eq!(
            remote_control_session_url(&remote_control_active_reply(
                "https://claude.ai/code/session_01?x=1"
            ))
            .as_deref(),
            Some("https://claude.ai/code/session_01?x=1")
        );
        assert_eq!(remote_control_session_url("no url here"), None);
        assert_eq!(
            remote_control_session_url("see http://claude.ai/code/x or https://"),
            None,
            "plain http and a bare scheme are no session URL"
        );
    }

    /// Drive one top-level `agent_message_chunk` through
    /// `emit_conversation_update` with `cb`'s pending command.
    async fn drive_agent_text(
        state: &Arc<RwLock<SessionState>>,
        cb: &mut CodeBuddyLiveState,
        text: &str,
        parent_tool_use_id: Option<&str>,
    ) {
        let mut update = serde_json::json!({
            "sessionUpdate": "agent_message_chunk",
            "content": {"type": "text", "text": text},
        });
        if let Some(parent) = parent_tool_use_id {
            update["_meta"] = serde_json::json!({"claudeCode": {"parentToolUseId": parent}});
        }
        let update: SessionUpdate =
            serde_json::from_value(update).expect("valid agent_message_chunk wire shape");
        let mut cache = ToolCallOutputCache::default();
        emit_conversation_update(
            state,
            &EventEmitter::Noop,
            AgentType::ClaudeCode,
            update,
            None,
            &mut cache,
            cb,
            None,
        )
        .await;
    }

    fn remote_control_events(state: &SessionState) -> Vec<Option<RemoteControlInfo>> {
        state
            .recent_events_after(0)
            .unwrap_or_default()
            .iter()
            .filter_map(|e| match &e.payload {
                AcpEvent::RemoteControl { remote_control } => Some(remote_control.clone()),
                _ => None,
            })
            .collect()
    }

    /// The reply to a pending command becomes a `RemoteControl` event after
    /// the text itself, which still renders; the command is then spent. Text
    /// before the reply, a subagent's text, and text with no command pending
    /// say nothing.
    #[tokio::test]
    async fn the_adapters_reply_to_a_pending_command_sets_remote_control() {
        let state = Arc::new(RwLock::new(SessionState::new(
            "conn-rc".to_string(),
            AgentType::ClaudeCode,
            None,
            "win".to_string(),
            None,
        )));
        let url = "https://claude.ai/code/session_01";
        let mut cb = CodeBuddyLiveState::default();

        drive_agent_text(&state, &mut cb, &remote_control_active_reply(url), None).await;
        assert!(
            remote_control_events(&*state.read().await).is_empty(),
            "no command pending: an agent that merely says so changes nothing"
        );

        cb.claude_remote_control = Some(RemoteControlCommand::Connect);
        drive_agent_text(&state, &mut cb, "some straggler", None).await;
        drive_agent_text(
            &state,
            &mut cb,
            &remote_control_active_reply(url),
            Some("toolu_1"),
        )
        .await;
        assert!(remote_control_events(&*state.read().await).is_empty());
        assert_eq!(
            cb.claude_remote_control,
            Some(RemoteControlCommand::Connect)
        );

        drive_agent_text(&state, &mut cb, &remote_control_active_reply(url), None).await;
        let on = Some(RemoteControlInfo {
            session_url: Some(url.to_string()),
        });
        assert_eq!(state.read().await.remote_control, on);
        assert_eq!(
            cb.claude_remote_control, None,
            "the reply spends the command"
        );
        let events = state
            .read()
            .await
            .recent_events_after(0)
            .unwrap_or_default();
        let reply_at = events
            .iter()
            .position(|e| {
                matches!(&e.payload, AcpEvent::ContentDelta { text, .. } if text.starts_with("Remote Control is active"))
            })
            .expect("the reply renders");
        let state_at = events
            .iter()
            .position(|e| matches!(e.payload, AcpEvent::RemoteControl { .. }))
            .expect("Remote Control is reported");
        assert!(reply_at < state_at);

        // Spent: the same words again change nothing.
        drive_agent_text(
            &state,
            &mut cb,
            "Remote Control is off. Run /remote-control to reconnect.",
            None,
        )
        .await;
        assert_eq!(state.read().await.remote_control, on);

        cb.claude_remote_control = Some(RemoteControlCommand::Disconnect);
        drive_agent_text(
            &state,
            &mut cb,
            "Remote Control is off. Run /remote-control to reconnect.",
            None,
        )
        .await;
        assert_eq!(state.read().await.remote_control, None);
        assert_eq!(remote_control_events(&*state.read().await), vec![on, None]);
    }

    // --- live ACP session title (`session_info_update.title`) --------------

    /// Drive one `session_info_update` carrying `title` through
    /// `emit_conversation_update`.
    async fn drive_session_info_title(state: &Arc<RwLock<SessionState>>, title: &str) {
        drive_session_info_title_from(state, AgentType::CodeBuddy, title).await;
    }

    /// [`drive_session_info_title`] for `agent_type`.
    async fn drive_session_info_title_from(
        state: &Arc<RwLock<SessionState>>,
        agent_type: AgentType,
        title: &str,
    ) {
        let update: SessionUpdate = serde_json::from_value(serde_json::json!({
            "sessionUpdate": "session_info_update",
            "title": title,
        }))
        .expect("valid session_info_update wire shape");
        let mut cache = ToolCallOutputCache::default();
        let mut cb = CodeBuddyLiveState::default();
        emit_conversation_update(
            state,
            &EventEmitter::Noop,
            agent_type,
            update,
            None,
            &mut cache,
            &mut cb,
            None,
        )
        .await;
    }

    /// Titles emitted on this connection so far, oldest first.
    async fn emitted_native_titles(state: &Arc<RwLock<SessionState>>) -> Vec<String> {
        state
            .read()
            .await
            .recent_events_after(0)
            .unwrap_or_default()
            .iter()
            .filter_map(|e| match &e.payload {
                AcpEvent::NativeSessionTitle { title } => Some(title.clone()),
                _ => None,
            })
            .collect()
    }

    fn title_test_state(conversation_id: Option<i32>) -> Arc<RwLock<SessionState>> {
        let mut st = SessionState::new(
            "conn-title".to_string(),
            AgentType::CodeBuddy,
            None,
            "win".to_string(),
            None,
        );
        st.conversation_id = conversation_id;
        Arc::new(RwLock::new(st))
    }

    /// A changed title emits; the SAME title arriving again does not. CodeBuddy
    /// (`sendPendingTitleUpdate`) resends its 80-code-unit fallback after every
    /// completed prompt with no last-sent guard of its own, and that string
    /// differs from the 100-char title our own parser derives from the same
    /// first message — so without this skip the sidebar name would flip on
    /// every turn (live write, then session-file parse, repeat).
    #[tokio::test]
    async fn session_info_title_emits_once_and_skips_an_identical_repeat() {
        let state = title_test_state(Some(7));

        drive_session_info_title(&state, "Fix the login flow").await;
        drive_session_info_title(&state, "Fix the login flow").await;
        drive_session_info_title(&state, "  Fix the login flow  ").await; // same after trim
        drive_session_info_title(&state, "Fix the signup flow").await;

        assert_eq!(
            emitted_native_titles(&state).await,
            vec![
                "Fix the login flow".to_string(),
                "Fix the signup flow".to_string()
            ],
            "only a CHANGED title may reach the lifecycle worker"
        );
    }

    /// A title published before the first prompt binds the row has nowhere to
    /// land, so it is dropped — and deliberately NOT remembered, so the resend
    /// that follows `ConversationLinked` is still accepted. Guards the
    /// `conversation_id.is_some()` half of the skip: a stale cache here would
    /// leave the row "Untitled" for the rest of the connection.
    #[tokio::test]
    async fn session_info_title_dropped_while_unbound_is_accepted_after_link() {
        let state = title_test_state(None);

        drive_session_info_title(&state, "Fix the login flow").await;
        assert!(
            emitted_native_titles(&state).await.is_empty(),
            "no row to write to yet"
        );
        assert!(
            state.read().await.last_native_title.is_none(),
            "a dropped title must not poison the skip-cache"
        );

        state
            .write()
            .await
            .apply_event(&AcpEvent::ConversationLinked {
                conversation_id: 7,
                folder_id: 1,
                parent_conversation_id: None,
                parent_tool_use_id: None,
            });

        drive_session_info_title(&state, "Fix the login flow").await;
        assert_eq!(
            emitted_native_titles(&state).await,
            vec!["Fix the login flow".to_string()],
            "the same title must be accepted once the row exists"
        );
    }

    /// Claude Code's live title is not written from the wire: when the CLI
    /// cannot generate a title, claude-agent-acp publishes the session's
    /// newest `last-prompt` record instead (measured on 0.89.1, registry
    /// (qqq)), which the history parser never produces, so writing it would
    /// flip the row on every detail fetch. It is held, normalized, for the
    /// transcript watcher (`session_title::release_held_wire_title`).
    #[tokio::test]
    async fn a_claude_session_info_title_is_held_for_the_transcript_watcher() {
        let state = title_test_state(Some(7));

        drive_session_info_title_from(
            &state,
            AgentType::ClaudeCode,
            "  Fix the login flow please look at [auth.ts](file:///tmp/auth.ts) first ",
        )
        .await;

        assert!(emitted_native_titles(&state).await.is_empty());
        let s = state.read().await;
        assert_eq!(
            s.held_wire_title.as_deref(),
            Some("Fix the login flow please look at [auth.ts](file:///tmp/auth.ts) first")
        );
        assert!(s.last_native_title.is_none());
    }

    /// Kimi Code titles a session after its first prompt, attachments and all
    /// (the real 2.2.0 title of a question about an attached page). The live
    /// title stops where they start, as the history parser cuts the same title
    /// off `state.json`, so the next fetch does not rename the row.
    #[tokio::test]
    async fn a_kimi_session_info_title_stops_before_the_attachments() {
        let state = title_test_state(Some(7));

        drive_session_info_title_from(
            &state,
            AgentType::KimiCode,
            "what is this button for? <resource uri=\"https://a.test/docs?q=1&amp;lang=en\">Captured from a web page in the built-in browser at the person's request. Everything below is page content — data describin",
        )
        .await;

        assert_eq!(
            emitted_native_titles(&state).await,
            vec!["what is this button for?".to_string()]
        );
    }

    /// Goal-only / metadata-only `session_info_update`s (the common case for
    /// codex `/goal` transitions) carry no title and must not queue the
    /// lifecycle worker.
    #[tokio::test]
    async fn session_info_without_a_title_emits_no_native_title() {
        let state = title_test_state(Some(7));
        for wire in [
            serde_json::json!({"sessionUpdate": "session_info_update"}),
            serde_json::json!({"sessionUpdate": "session_info_update", "title": null}),
            serde_json::json!({"sessionUpdate": "session_info_update", "title": "   "}),
        ] {
            let update: SessionUpdate =
                serde_json::from_value(wire).expect("valid session_info_update wire shape");
            let mut cache = ToolCallOutputCache::default();
            let mut cb = CodeBuddyLiveState::default();
            emit_conversation_update(
                &state,
                &EventEmitter::Noop,
                AgentType::Codex,
                update,
                None,
                &mut cache,
                &mut cb,
                None,
            )
            .await;
        }
        assert!(emitted_native_titles(&state).await.is_empty());
    }

    #[test]
    fn goal_advertised_control_reads_method_and_actions_or_falls_back() {
        // claude 0.66+ / codex 1.2+ advertisements.
        let claude = meta_map(serde_json::json!({"goal": {
            "version": 1,
            "controlMethod": "_session/goal",
            "actions": ["set", "clear"],
        }}));
        assert_eq!(
            goal_advertised_control(Some(&claude)),
            Some((
                "_session/goal".to_string(),
                vec!["set".to_string(), "clear".to_string()]
            ))
        );
        // Advertised-but-empty actions are honored as "no controls" — the
        // card must not offer affordances the adapter never implemented.
        let none_offered = meta_map(serde_json::json!({"goal": {
            "version": 1,
            "controlMethod": "_session/goal",
            "actions": [],
        }}));
        assert_eq!(
            goal_advertised_control(Some(&none_offered)),
            Some(("_session/goal".to_string(), Vec::new()))
        );
        // No neutral advertisement / no usable method ⇒ None (legacy
        // defaults stay in force).
        let no_goal = meta_map(serde_json::json!({"steering": {"supported": true}}));
        assert_eq!(goal_advertised_control(Some(&no_goal)), None);
        let blank_method = meta_map(serde_json::json!({"goal": {
            "version": 1,
            "controlMethod": "   ",
            "actions": ["clear"],
        }}));
        assert_eq!(goal_advertised_control(Some(&blank_method)), None);
        assert_eq!(goal_advertised_control(None), None);
    }

    #[test]
    fn the_legacy_vocabulary_is_resolved_at_initialize_not_at_construction() {
        // A fresh session knows NOTHING: a snapshot read during the handshake
        // (which happens — `spawn_agent` returns before `initialize` lands)
        // must not hand the card a legacy pair it latches forever.
        let fresh = SessionState::new(
            "c-goal".to_string(),
            AgentType::ClaudeCode,
            None,
            "w".to_string(),
            None,
        );
        assert_eq!(fresh.goal_actions, None);
        assert_eq!(fresh.to_snapshot().goal_actions, None);
        // ... and `None` reaches the client as an explicit null, not as an
        // absent field — absent is reserved for a server too old to have it,
        // which the client still maps to the legacy pair.
        let wire = serde_json::to_value(fresh.to_snapshot()).unwrap();
        assert_eq!(wire.get("goal_actions"), Some(&serde_json::Value::Null));

        // Initialize is where both cases are decided. Advertised wins…
        assert_eq!(
            resolve_goal_control(Some((
                "_session/goal".to_string(),
                vec!["set".to_string(), "clear".to_string()],
            ))),
            (
                Some("_session/goal".to_string()),
                vec!["set".to_string(), "clear".to_string()]
            )
        );
        // …and a non-advertising adapter resolves to the legacy pair, keeping
        // the method the state was built with.
        assert_eq!(
            resolve_goal_control(None),
            (None, vec!["pause".to_string(), "clear".to_string()])
        );
    }

    #[test]
    fn regression_initialize_capabilities_apply_without_delegate_injection() {
        let mut state = SessionState::new(
            "c-goal-no-companion".to_string(),
            AgentType::ClaudeCode,
            None,
            "w".to_string(),
            None,
        );

        apply_initialized_connection_capabilities(
            &mut state,
            true,
            None,
            true,
            Some((
                "_session/goal".to_string(),
                vec!["set".to_string(), "clear".to_string()],
            )),
            None,
        );

        assert!(state.native_steering_available);
        assert!(state.neutral_goal_channel);
        assert_eq!(state.goal_control_method, "_session/goal");
        assert_eq!(
            state.goal_actions,
            Some(vec!["set".to_string(), "clear".to_string()])
        );
        assert_eq!(state.delegation_token, None);
        assert!(!state.feedback_tool_available);
    }

    #[test]
    fn air_session_failure_requires_wellformed_versioned_envelope() {
        let ok = meta_map(serde_json::json!({"jetbrains": {"air": {
            "version": 1,
            "sessionFailure": {"id": "t1:error", "revision": 1},
        }}}));
        assert!(air_session_failure(Some(&ok)).is_some());

        // Missing/zero/stringly version, or a failure outside the air
        // envelope, must yield nothing.
        for bad in [
            serde_json::json!({"jetbrains": {"air": {"sessionFailure": {"id": "x", "revision": 1}}}}),
            serde_json::json!({"jetbrains": {"air": {"version": 0, "sessionFailure": {}}}}),
            serde_json::json!({"jetbrains": {"air": {"version": "1", "sessionFailure": {}}}}),
            serde_json::json!({"jetbrains": {"sessionFailure": {"id": "x", "revision": 1}}}),
            serde_json::json!({"air": {"version": 1, "sessionFailure": {}}}),
        ] {
            let meta = meta_map(bad);
            assert!(air_session_failure(Some(&meta)).is_none());
        }
        assert!(air_session_failure(None).is_none());
    }

    #[test]
    fn response_session_failure_reads_the_prompt_response_carrier() {
        // claude `failActiveWithSessionFailure` / codex
        // `terminalFailurePromptResponse` both attach a turn's terminal record
        // to the prompt response `_meta` under the SAME jetbrains.air envelope
        // the update channel uses, with a disguised `end_turn` stop reason —
        // this carrier is the only wire delivery of claude terminal failures.
        let meta = meta_map(serde_json::json!({"jetbrains": {"air": {
            "version": 1,
            "sessionFailure": {
                "id": "prompt-1:error",
                "revision": 6,
                "category": "connection",
                "severity": "error",
                "title": "The connection to Claude was lost.",
                "actions": ["new_session"],
            },
        }}}));
        let record = response_session_failure(Some(&meta)).expect("record");
        assert_eq!(record.id, "prompt-1:error");
        assert_eq!(record.revision, 6);
        assert_eq!(record.severity, "error");
        assert_eq!(record.actions, vec!["new_session".to_string()]);

        // Same gates as the update channel: malformed envelope or missing
        // identity ⇒ no record (and no synthetic-empty suppression).
        let unversioned = meta_map(serde_json::json!({"jetbrains": {"air": {
            "sessionFailure": {"id": "x", "revision": 1},
        }}}));
        assert!(response_session_failure(Some(&unversioned)).is_none());
        let no_identity = meta_map(serde_json::json!({"jetbrains": {"air": {
            "version": 1,
            "sessionFailure": {"title": "no id"},
        }}}));
        assert!(response_session_failure(Some(&no_identity)).is_none());
        assert!(response_session_failure(None).is_none());
    }

    #[test]
    fn parse_session_failure_record_requires_identity_and_stays_lenient() {
        // The real codex shape (SESSION_FAILURE_POLICY: auth_required →
        // access/[login]).
        let full = serde_json::json!({
            "id": "turn-9:error",
            "revision": 2,
            "category": "access",
            "severity": "error",
            "title": "Authentication required.",
            "details": "Token expired",
            "actions": ["login"],
        });
        let record = parse_session_failure_record(&full).expect("record");
        assert_eq!(record.id, "turn-9:error");
        assert_eq!(record.revision, 2);
        assert_eq!(record.category, "access");
        assert_eq!(record.severity, "error");
        assert_eq!(record.title, "Authentication required.");
        assert_eq!(record.details.as_deref(), Some("Token expired"));
        assert_eq!(record.actions, vec!["login".to_string()]);
        assert!(!record.resolved);

        // id + revision are HARD requirements — no identity, no merge.
        for bad in [
            serde_json::json!({"revision": 1, "title": "x"}),
            serde_json::json!({"id": "", "revision": 1}),
            serde_json::json!({"id": "   ", "revision": 1}),
            serde_json::json!({"id": "x", "title": "no revision"}),
            serde_json::json!({"id": "x", "revision": 0}),
            serde_json::json!({"id": "x", "revision": -1}),
            serde_json::json!({"id": "x", "revision": "1"}),
        ] {
            assert!(parse_session_failure_record(&bad).is_none(), "{bad:?}");
        }

        // Everything else is lenient: unknown vocabulary passes through as
        // strings, blanks default, non-string action entries are skipped.
        let sparse = serde_json::json!({
            "id": "notice-1",
            "revision": 1,
            "category": "quantum",
            "actions": ["retry", 42, "sing"],
        });
        let record = parse_session_failure_record(&sparse).expect("record");
        assert_eq!(record.category, "quantum");
        assert_eq!(record.severity, "error");
        assert_eq!(record.title, "");
        assert_eq!(record.details, None);
        assert_eq!(
            record.actions,
            vec!["retry".to_string(), "sing".to_string()]
        );
    }

    /// claude-agent-acp 0.74.0's mid-session sign-out record, verbatim off the
    /// `session_info_update` channel (`sessionFailureMeta`: id, revision,
    /// category, severity, title, details, actions — `kind`/`recoveryPolicy`
    /// stay agent-internal). Two things in it changed with that release and
    /// are worth pinning:
    ///
    /// * the CLI's own "… Please run /login" prose moved OUT of `title` into
    ///   `details`, leaving the policy's client-neutral fallback as the title —
    ///   so the strip reads as a heading with the TUI advice behind its
    ///   expander, not the other way round;
    /// * the record may carry a `reason` refinement. codeg never produces one
    ///   (it is `--hide-claude-auth`-only; see the registry entry), and the
    ///   parser reads fields individually, so an unknown key must simply ride
    ///   through instead of failing the record.
    #[test]
    fn parse_session_failure_record_reads_claude_074_sign_out() {
        let signed_out = serde_json::json!({
            "id": "sess-7:session-error:epoch-1:1",
            "revision": 1,
            "category": "access",
            "severity": "error",
            "title": "Sign in to continue using Claude.",
            "details": "Invalid API key · Please run /login",
            "actions": ["login"],
        });
        let record = parse_session_failure_record(&signed_out).expect("record");
        assert_eq!(record.category, "access");
        assert_eq!(record.severity, "error");
        assert_eq!(record.title, "Sign in to continue using Claude.");
        assert_eq!(
            record.details.as_deref(),
            Some("Invalid API key · Please run /login")
        );
        // The banner renders a Login button off exactly this.
        assert_eq!(record.actions, vec!["login".to_string()]);

        // Same record plus the release's new refinement: parsed identically.
        let mut with_reason = signed_out.clone();
        with_reason["reason"] = serde_json::json!("claude_subscription_not_supported");
        assert_eq!(
            parse_session_failure_record(&with_reason).expect("record"),
            record
        );
    }

    #[test]
    fn client_capabilities_advertise_air_for_claude_and_codex_only() {
        // Both AIR speakers must send EXACTLY the shape the adapters gate on:
        // integer version >= 1 plus "sessionFailure" in the capabilities
        // array (`clientSupportsTypedSessionFailures` in codex,
        // `supportsAirSessionFailures` in claude).
        for agent in [AgentType::ClaudeCode, AgentType::Codex] {
            let caps =
                serde_json::to_value(build_client_capabilities(agent, HostToolsPolicy::Default))
                    .unwrap();
            let air = caps
                .get("_meta")
                .and_then(|m| m.get("jetbrains"))
                .and_then(|j| j.get("air"))
                .unwrap_or_else(|| panic!("{agent:?} must advertise jetbrains.air"));
            assert_eq!(air.get("version").and_then(|v| v.as_i64()), Some(1));
            let capabilities = air
                .get("capabilities")
                .and_then(|c| c.as_array())
                .unwrap_or_else(|| panic!("{agent:?} must advertise an AIR capabilities array"));
            assert!(capabilities
                .iter()
                .any(|v| v.as_str() == Some("sessionFailure")));
            // And exactly this much. Adding a capability here is not free — it
            // is what turns the corresponding behavior on.
            //
            // "asyncTasks" IS wanted, from BOTH (claude-agent-acp 0.73.0,
            // codex-acp 1.10.0): it is the only channel that reports whether an
            // agent's background work is still alive, and the only one that can
            // stop it.
            //
            // The other two stay out. "agentFileChangeReport"
            // (claude-agent-acp 0.69.0 / codex-acp 1.4.0) buys an extra model
            // round-trip per turn for a clamped, self-reported subset of what
            // the `workspace_state` watcher already sees, and
            // "nativeSubagentSessions" would make both adapters SUPPRESS the
            // `Agent`/`Task` tool call that codeg builds its whole subagent
            // rendering around, replacing it with an announcement that carries
            // no parent tool-use id to rebuild it from. See the reasoning at
            // the advertisement site before relaxing this.
            //
            // "diffPatch" (codex-acp 2.0.0) is codex's alone: it trades 2.0.0's
            // per-hunk text fragments for one exact Git patch per file. claude
            // would send its patch in the permission request, whose placeholder
            // text the permission card cannot tell from an emptied file. Also
            // left out: "rawInputRendering" (it removes the question text a
            // message-only MCP elicitation's permission card shows) and
            // "planFile" (the plan card renders the plan TEXT).
            let mut expected: Vec<serde_json::Value> = vec![
                "sessionFailure".into(),
                "asyncTasks".into(),
                "recommendedValue".into(),
            ];
            if agent == AgentType::Codex {
                expected.push("diffPatch".into());
            }
            assert_eq!(
                capabilities, &expected,
                "{agent:?} advertises an unexpected AIR capability set"
            );
        }
        // Claude keeps its subagent-transcript flag alongside.
        let claude = serde_json::to_value(build_client_capabilities(
            AgentType::ClaudeCode,
            HostToolsPolicy::Default,
        ))
        .unwrap();
        assert_eq!(
            claude
                .get("_meta")
                .and_then(|m| m.get("subagent-transcript"))
                .and_then(|v| v.as_bool()),
            Some(true)
        );
        // Non-AIR agents advertise nothing under jetbrains.
        for agent in [AgentType::Gemini, AgentType::Grok, AgentType::OpenCode] {
            let caps =
                serde_json::to_value(build_client_capabilities(agent, HostToolsPolicy::Default))
                    .unwrap();
            assert!(caps.get("_meta").and_then(|m| m.get("jetbrains")).is_none());
        }
    }

    /// codex gets `terminal_output_delta` (its completion frames stop repeating
    /// the output the bridge already streamed); claude must NOT — there the
    /// same key moves shell output onto a `_meta` channel codeg does not
    /// bridge. Neither may get the other spelling: it would move codex's shell
    /// output onto `terminal_output`, a key its bridge does not read.
    #[test]
    fn client_capabilities_advertise_terminal_output_delta_to_codex_only() {
        let meta_of = |agent| {
            serde_json::to_value(build_client_capabilities(agent, HostToolsPolicy::Default))
                .unwrap()
                .get("_meta")
                .cloned()
                .unwrap_or_default()
        };
        let codex = meta_of(AgentType::Codex);
        assert_eq!(
            codex.get("terminal_output_delta").and_then(|v| v.as_bool()),
            Some(true)
        );
        assert!(codex.get("terminal_output").is_none());
        for agent in [
            AgentType::ClaudeCode,
            AgentType::Pi,
            AgentType::Gemini,
            AgentType::Grok,
        ] {
            let meta = meta_of(agent);
            assert!(meta.get("terminal_output_delta").is_none(), "{agent:?}");
            assert!(meta.get("terminal_output").is_none(), "{agent:?}");
        }
    }

