    fn test_delegation_injection(
        agent_availability: Arc<dyn AgentAvailabilityLookup>,
    ) -> DelegationInjection {
        use crate::acp::delegation::broker::DelegationBroker;
        use crate::acp::delegation::listener::TokenRegistry;
        use crate::acp::delegation::spawner::{mock::MockSpawner, ConnectionSpawner};

        let broker = Arc::new(DelegationBroker::new(
            Arc::new(MockSpawner::default()) as Arc<dyn ConnectionSpawner>,
            Arc::new(TestConversationDepthLookup)
                as Arc<dyn crate::acp::delegation::broker::ConversationDepthLookup>,
        ));
        DelegationInjection {
            broker,
            continuation_coordinator: std::sync::Weak::new(),
            parent_connection_exit_causes: Arc::new(ParentConnectionExitCauses::default()),
            tokens: Arc::new(TokenRegistry::default()),
            leases: Arc::new(crate::acp::delegation::lease::CompanionLeaseRegistry::default()),
            socket_path: std::path::PathBuf::from("/tmp/codeg-mcp.sock"),
            agent_availability,
            feedback: crate::acp::feedback::FeedbackRuntimeConfig::new(),
            ask: crate::acp::question::QuestionRuntimeConfig::new(),
            sessions: crate::acp::session_info::SessionInfoRuntimeConfig::new(),
            authoring: crate::acp::chat_authoring::ChatAuthoringRuntimeConfig::new(),
            browser: crate::acp::browser_tools::BrowserToolsRuntimeConfig::new(),
            computer: crate::acp::computer_tools::ComputerToolsRuntimeConfig::new(),
            questions: Arc::new(TestNoQuestions)
                as Arc<dyn crate::acp::question::SessionQuestionAccess>,
            supervisor_wake: crate::acp::delegation::supervisor::SupervisorWake::noop(),
            metrics: Arc::new(crate::acp::delegation::metrics::DelegationMetrics::default()),
            plan_approvals: Arc::new(TestNoPlanApprovals)
                as Arc<dyn crate::acp::plan_approval::SessionPlanApprovalAccess>,
        }
    }

    // ─── inject_codeg_mcp: enabled=false short-circuit ──────────
    #[test]
    fn grok_transport_policy_warns_and_preserves_nonvisual_tools() {
        let all = CompanionFeatureFlags {
            delegation: true,
            coordination_v1: true,
            feedback: true,
            sessions: true,
            tasks: true,
            automations: true,
            taskboard: true,
            browser: true,
            browser_eval: true,
            computer: true,
            computer_launch: true,
            computer_clipboard: true,
            ..CompanionFeatureFlags::default()
        };
        let mut flags = all;
        let notice = apply_companion_transport_policy(AgentType::Grok, &mut flags)
            .expect("omitted groups must be disclosed");
        assert_eq!(notice.severity, "warning");
        assert!(notice.title.contains("Grok"));
        assert!(!flags.browser && !flags.browser_eval);
        assert!(!flags.computer && !flags.computer_launch && !flags.computer_clipboard);
        assert_eq!(
            companion_features_arg(flags).as_deref(),
            Some("delegation,coordination_v1,feedback,sessions,tasks,automations,taskboard")
        );
        assert!(apply_companion_transport_policy(AgentType::Grok, &mut flags).is_none());
        let mut other = all;
        assert!(apply_companion_transport_policy(AgentType::Codex, &mut other).is_none());
        assert_eq!(other, all);
    }

