    #[test]
    fn delegate_target_args_filter_disabled_agents() {
        use crate::acp::custom_registry::{
            hydrate, hydrate_test_guard, CustomAgentDef, CustomAgentSpec, CustomDistributionKind,
            NpxSpec,
        };
        let _guard = hydrate_test_guard();
        let def = |id: &str| CustomAgentDef {
            registry_id: id.into(),
            name: id.into(),
            description: String::new(),
            version: "1.0.0".into(),
            distribution_kind: CustomDistributionKind::Npx,
            spec: CustomAgentSpec {
                npx: Some(NpxSpec {
                    package: format!("{id}@1.0.0"),
                    ..Default::default()
                }),
                ..Default::default()
            },
            icon_url: None,
            skills_shared_store: false,
            skills_dir: None,
            source: Default::default(),
            version_probe: None,
            supports_mcp: true,
        };
        assert!(hydrate(&[def("delegate-on"), def("delegate-off")]).is_empty());

        let disabled = vec![
            "grok".to_string(),
            "codex".to_string(),
            "custom:delegate-off".to_string(),
        ];
        let (custom_slugs, disabled_builtins) = delegate_target_args(&disabled);
        assert_eq!(custom_slugs, vec!["custom:delegate-on".to_string()]);
        assert_eq!(
            disabled_builtins,
            vec!["codex".to_string(), "grok".to_string()],
            "builtins only, sorted for a deterministic arg string"
        );

        let (custom_slugs, disabled_builtins) = delegate_target_args(&[]);
        assert_eq!(
            custom_slugs,
            vec![
                "custom:delegate-off".to_string(),
                "custom:delegate-on".to_string()
            ]
        );
        assert!(disabled_builtins.is_empty());

        hydrate(&[]);
    }

    // ─── companion_features_arg: inject/skip decision + --features value ──
    //
    // The companion now carries two independently-toggled tool groups. It is
    // injected when EITHER is on, and the `--features` arg names exactly the
    // enabled groups so the companion hides the rest. Crucially, feedback alone
    // must still inject the companion (the historical delegation-only gate would
    // have skipped it).

    /// Post-ready unavailability helper carries the stable audit code without
    /// inventing a second metrics Arc or mutating route plan fields.
    #[tokio::test]
    async fn post_ready_unavailable_audit_stable_code_no_route_mutation() {
        use crate::acp::delegation::metrics::{DelegationAuditRecord, DELEGATION_UNAVAILABLE_CODE};
        use crate::acp::delegation::route::{
            DelegationRoutePlan, DelegationRoutePolicy, DelegationRouteSource,
            NativeSuppressionPlan, ROUTE_ADAPTER_CONTRACT_VERSION,
        };
        use crate::acp::session_state::SessionState;
        use crate::web::event_bridge::EventEmitter;

        let plan = DelegationRoutePlan {
            managed: true,
            requested: DelegationRoutePolicy::Codeg,
            effective: DelegationRoutePolicy::Codeg,
            source: DelegationRouteSource::GlobalDefault,
            native_suppression: NativeSuppressionPlan::CodexMultiAgentFalse,
            expose_codeg_delegation: true,
            degraded_reason: None,
            adapter_contract_version: ROUTE_ADAPTER_CONTRACT_VERSION.to_string(),
            fingerprint: "test-ready-avail".into(),
        };
        let state = Arc::new(tokio::sync::RwLock::new(SessionState::new(
            "conn-avail-test".into(),
            AgentType::Codex,
            None,
            "win".into(),
            None,
        )));
        {
            let mut s = state.write().await;
            s.set_route_plan_snapshot(&plan);
            s.set_delegation_available(true);
            s.conversation_id = Some(7);
        }
        let route_before = state.read().await.delegation_route.clone();
        assert!(route_before.delegation_available);
        assert_eq!(route_before.effective, DelegationRoutePolicy::Codeg);
        assert!(route_before.degraded_reason.is_none());

        // Reuse audit constructor (same as finish_route_ready monitor path).
        let audit =
            DelegationAuditRecord::availability("conn-avail-test", Some(7), AgentType::Codex);
        assert_eq!(audit.stable_code(), Some(DELEGATION_UNAVAILABLE_CODE));
        emit_post_ready_unavailable(
            &state,
            &EventEmitter::Noop,
            "conn-avail-test",
            Some(7),
            AgentType::Codex,
        )
        .await;

        let after = state.read().await.delegation_route.clone();
        assert!(!after.delegation_available, "availability must flip false");
        assert_eq!(
            after.effective, route_before.effective,
            "immutable route fields must not change"
        );
        assert_eq!(after.requested, route_before.requested);
        assert_eq!(after.source, route_before.source);
        assert_eq!(after.managed, route_before.managed);
        assert_eq!(after.degraded_reason, route_before.degraded_reason);
    }

    /// Ready success must emit `available: true` so web clients that attached
    /// during bootstrap (snapshot still false) unstick the banner. Route fields
    /// stay immutable. Mirrors the emit used by `finish_route_ready`.
    #[tokio::test]
    async fn finish_route_ready_success_emits_availability_true_no_route_mutation() {
        use crate::acp::delegation::route::{
            DelegationRoutePlan, DelegationRoutePolicy, DelegationRouteSource,
            NativeSuppressionPlan, ROUTE_ADAPTER_CONTRACT_VERSION,
        };
        use crate::acp::session_state::SessionState;
        use crate::web::event_bridge::{emit_with_state, EventEmitter};

        let plan = DelegationRoutePlan {
            managed: true,
            requested: DelegationRoutePolicy::Codeg,
            effective: DelegationRoutePolicy::Codeg,
            source: DelegationRouteSource::GlobalDefault,
            native_suppression: NativeSuppressionPlan::CodexMultiAgentFalse,
            expose_codeg_delegation: true,
            degraded_reason: None,
            adapter_contract_version: ROUTE_ADAPTER_CONTRACT_VERSION.to_string(),
            fingerprint: "test-ready-avail-true".into(),
        };
        let state = Arc::new(tokio::sync::RwLock::new(SessionState::new(
            "conn-avail-true".into(),
            AgentType::Codex,
            None,
            "win".into(),
            None,
        )));
        {
            let mut s = state.write().await;
            s.set_route_plan_snapshot(&plan);
            // Bootstrap snapshot: attached before ready, availability still false.
            s.set_delegation_available(false);
        }
        let route_before = state.read().await.delegation_route.clone();
        assert!(!route_before.delegation_available);
        assert_eq!(route_before.effective, DelegationRoutePolicy::Codeg);

        emit_with_state(
            &state,
            &EventEmitter::Noop,
            AcpEvent::DelegationAvailabilityChanged { available: true },
        )
        .await;

        let after = state.read().await.delegation_route.clone();
        assert!(after.delegation_available, "availability must flip true");
        assert_eq!(
            after.effective, route_before.effective,
            "immutable route fields must not change"
        );
        assert_eq!(after.requested, route_before.requested);
        assert_eq!(after.source, route_before.source);
        assert_eq!(after.managed, route_before.managed);
        assert_eq!(after.degraded_reason, route_before.degraded_reason);
    }

    #[test]
    fn companion_features_follow_plan_not_live_broker_route_setting() {
        // Plan-driven feature helper: expose_codeg_delegation maps to
        // delegation + coordination_v1 — never a live Broker re-read.
        assert_eq!(
            companion_features_arg(CompanionFeatureFlags {
                delegation: true,
                coordination_v1: true,
                feedback: true,
                ..CompanionFeatureFlags::default()
            }),
            Some("delegation,coordination_v1,feedback".into())
        );
        assert_eq!(
            companion_features_arg(CompanionFeatureFlags {
                feedback: true,
                ..CompanionFeatureFlags::default()
            }),
            Some("feedback".into())
        );
        assert_eq!(
            companion_features_arg(CompanionFeatureFlags::default()),
            None
        );
    }

    #[test]
    fn companion_features_arg_names_each_group_the_companion_parses() {
        let only = |f: fn(&mut CompanionFeatureFlags)| {
            let mut flags = CompanionFeatureFlags::default();
            f(&mut flags);
            companion_features_arg(flags)
        };
        // Delegation only.
        assert_eq!(
            only(|f| f.delegation = true),
            Some("delegation".to_string())
        );
        // Feedback only — the decoupling: companion injected for feedback even
        // when delegation is off.
        assert_eq!(only(|f| f.feedback = true), Some("feedback".to_string()));
        // Ask only — likewise injects the companion on its own.
        assert_eq!(only(|f| f.ask = true), Some("ask".to_string()));
        // Sessions only — likewise injects the companion on its own.
        assert_eq!(only(|f| f.sessions = true), Some("sessions".to_string()));
        // Per-spawn tasks group: injects alone.
        assert_eq!(only(|f| f.tasks = true), Some("tasks".to_string()));
        // So does the per-spawn result group of a `codeg-cli` run's root.
        assert_eq!(only(|f| f.result = true), Some("result".to_string()));
        // Each chat-authoring group injects the companion on its own too, so a
        // user who only wants "create a task from chat" still gets the tool.
        assert_eq!(
            only(|f| f.automations = true),
            Some("automations".to_string())
        );
        assert_eq!(only(|f| f.taskboard = true), Some("taskboard".to_string()));
        // The browser group too — a user who only shares browser tabs still
        // gets a companion.
        assert_eq!(only(|f| f.browser = true), Some("browser".to_string()));
        // All on → comma-joined, in the order the companion parses.
        assert_eq!(
            companion_features_arg(CompanionFeatureFlags {
                delegation: true,
                feedback: true,
                ask: true,
                sessions: true,
                tasks: true,
                result: true,
                automations: true,
                taskboard: true,
                browser: true,
                browser_eval: true,
                computer: true,
                computer_launch: true,
                computer_clipboard: true,
                ..CompanionFeatureFlags::default()
            }),
            Some(
                "delegation,feedback,ask,sessions,tasks,result,automations,taskboard,browser,\
                 browser_eval,computer,computer_launch,computer_clipboard"
                    .to_string()
            )
        );
        assert_eq!(only(|f| f.computer_clipboard = true), None);
        // Computer use alone still gets a companion.
        assert_eq!(only(|f| f.computer = true), Some("computer".to_string()));
        // Its launch switch never travels on its own.
        assert_eq!(only(|f| f.computer_launch = true), None);
        // `browser_eval` never travels on its own: the companion requires both
        // tokens, and a lone one in an agent's MCP config would read as if it
        // granted something.
        assert_eq!(only(|f| f.browser_eval = true), None);
        assert_eq!(
            only(|f| {
                f.browser = true;
                f.browser_eval = true;
            }),
            Some("browser,browser_eval".to_string())
        );
    }

    #[test]
    fn companion_features_arg_inject_skip_decision() {
        // All off → no companion at all.
        assert_eq!(
            companion_features_arg(CompanionFeatureFlags {
                delegation: false,
                coordination_v1: false,
                feedback: false,
                ask: false,
                sessions: false,
                workflow_v2: false,
                ..CompanionFeatureFlags::default()
            }),
            None
        );
        // Delegation only without coordination → no Join token.
        assert_eq!(
            companion_features_arg(CompanionFeatureFlags {
                delegation: true,
                coordination_v1: false,
                feedback: false,
                ask: false,
                sessions: false,
                workflow_v2: false,
                ..CompanionFeatureFlags::default()
            }),
            Some("delegation".to_string())
        );
        // Delegation + coordination_v1 (production Codeg-delegation plan).
        assert_eq!(
            companion_features_arg(CompanionFeatureFlags {
                delegation: true,
                coordination_v1: true,
                feedback: false,
                ask: false,
                sessions: false,
                workflow_v2: false,
                ..CompanionFeatureFlags::default()
            }),
            Some("delegation,coordination_v1".to_string())
        );
        // Root + delegation enables workflow_v2 injection.
        assert_eq!(
            companion_features_arg(CompanionFeatureFlags {
                delegation: true,
                coordination_v1: true,
                feedback: false,
                ask: false,
                sessions: false,
                workflow_v2: true,
                ..CompanionFeatureFlags::default()
            }),
            Some("delegation,coordination_v1,workflow_v2".to_string())
        );
        // Feedback only — the decoupling: companion injected for feedback even
        // when delegation is off.
        assert_eq!(
            companion_features_arg(CompanionFeatureFlags {
                delegation: false,
                coordination_v1: false,
                feedback: true,
                ask: false,
                sessions: false,
                workflow_v2: false,
                ..CompanionFeatureFlags::default()
            }),
            Some("feedback".to_string())
        );
        // Ask only — likewise injects the companion on its own.
        assert_eq!(
            companion_features_arg(CompanionFeatureFlags {
                delegation: false,
                coordination_v1: false,
                feedback: false,
                ask: true,
                sessions: false,
                workflow_v2: false,
                ..CompanionFeatureFlags::default()
            }),
            Some("ask".to_string())
        );
        // Sessions only — likewise injects the companion on its own.
        assert_eq!(
            companion_features_arg(CompanionFeatureFlags {
                delegation: false,
                coordination_v1: false,
                feedback: false,
                ask: false,
                sessions: true,
                workflow_v2: false,
                ..CompanionFeatureFlags::default()
            }),
            Some("sessions".to_string())
        );
        // Workflow alone still injects (feature bit on without other groups).
        assert_eq!(
            companion_features_arg(CompanionFeatureFlags {
                delegation: false,
                coordination_v1: false,
                feedback: false,
                ask: false,
                sessions: false,
                workflow_v2: true,
                ..CompanionFeatureFlags::default()
            }),
            Some("workflow_v2".to_string())
        );
        // All on → comma-joined, in declaration order.
        assert_eq!(
            companion_features_arg(CompanionFeatureFlags {
                delegation: true,
                coordination_v1: true,
                feedback: true,
                ask: true,
                sessions: true,
                workflow_v2: true,
                ..CompanionFeatureFlags::default()
            }),
            Some("delegation,coordination_v1,feedback,ask,sessions,workflow_v2".to_string())
        );
    }

